import { MenuType } from "../Model/MenuType";
import { Meal } from "../Model/Meal";
import { Menu } from "../Model/Menu";
import { Dish } from "../Model/Dish";
import { DishType } from "../Model/DishType";
import { Recipe } from "../Model/Recipe";
import { Ingredient } from "../Model/Ingredient";
import { Product } from "../Model/Product";
import { Allergen } from "../Model/Allergen";
import { NutritionType } from "../Model/NutritionType";
import { Unit } from "../Model/Unit";
import { Canteen } from "../Model/Canteen";
import { Op } from "sequelize";

export class MenuService {

    async createMenu(data: {
        menuTypeId: number;
        initialDate: Date;
        finalDate: Date;
        meals: number[];
        status: "published" | "aproved" | "pending";
        canteenId: number;
    }) {
        if (data.finalDate <= data.initialDate) throw new Error("FINAL_DATE_MUST_BE_GREATER_THAN_INITIAL_DATE");
        
        const menuType = await MenuType.findByPk(data.menuTypeId);
        if (!menuType) throw new Error("MENU_TYPE_NOT_FOUND");

        // Validar se a cantina existe
        const canteen = await Canteen.findByPk(data.canteenId);
        if (!canteen) throw new Error("CANTEEN_NOT_FOUND");

        for (const mId of data.meals) {
            const meal = await Meal.findByPk(mId);
            if (!meal) throw new Error("MEAL_NOT_FOUND");
            // Validar se a meal pertence à mesma cantina
            if (meal.canteenId !== data.canteenId) {
                throw new Error("MEAL_CANTEEN_MISMATCH");
            }
        }

        return await Menu.create(data);
    }

    async listMenus() {
        return await Menu.findAll();
    }

    async getMenuById(id: number) {
        const menu = await Menu.findByPk(id);
        if (!menu) throw new Error("MENU_NOT_FOUND");
        return menu;
    }

    // Returns current week menu with days -> meals and each meal contains allergens (names)
    // and nutrition entries with typeId, name and aggregated percentage.
    async getCurrentWeekMenuDetailed(menuTypeId?: number, weekOffset: number = 0) {
        // Calcular a data da semana baseada no offset
        const today = new Date();
        today.setHours(0, 0, 0, 0);
        
        // Encontrar a segunda-feira da semana atual
        const dayOfWeek = today.getDay();
        const diff = dayOfWeek === 0 ? -6 : 1 - dayOfWeek; // Segunda-feira
        const mondayOfCurrentWeek = new Date(today);
        mondayOfCurrentWeek.setDate(today.getDate() + diff);
        
        // Aplicar offset de semanas
        const targetMonday = new Date(mondayOfCurrentWeek);
        targetMonday.setDate(mondayOfCurrentWeek.getDate() + (weekOffset * 7));
        targetMonday.setHours(0, 0, 0, 0);
        
        const targetSunday = new Date(targetMonday);
        targetSunday.setDate(targetMonday.getDate() + 6);
        targetSunday.setHours(23, 59, 59, 999);
        
        // Construir filtro para encontrar menu que se sobrepõe com a semana
        const whereClause: any = {
            initialDate: {
                [Op.lte]: targetSunday,
            },
            finalDate: {
                [Op.gte]: targetMonday,
            }
        };
        
        if (menuTypeId !== undefined) {
            whereClause.menuTypeId = menuTypeId;
        }
        
        // Tentar encontrar menu que se sobrepõe com a semana
        let menu = await Menu.findOne({ 
            where: whereClause,
            order: [["initialDate", "DESC"]] 
        });
        
        // Se não encontrar menu para a semana específica, retornar erro
        if (!menu) {
            throw new Error("MENU_NOT_FOUND");
        }
        
        // Para nursing homes, usar o intervalo completo do menu
        // Para schools, usar segunda a domingo
        let mealDateStart: Date;
        let mealDateEnd: Date;
        
        if (menuTypeId === 2) {
            // Nursing Home: usar todo o intervalo do menu
            mealDateStart = new Date(menu.initialDate);
            mealDateStart.setHours(0, 0, 0, 0);
            mealDateEnd = new Date(menu.finalDate);
            mealDateEnd.setHours(23, 59, 59, 999);
        } else {
            // School: usar apenas segunda a domingo da semana calculada
            mealDateStart = targetMonday;
            mealDateEnd = targetSunday;
        }

        // parse meal ids (menu.meals can be JSON or array)
        let mealIds: number[] = [];
        if (Array.isArray(menu.meals)) {
            mealIds = menu.meals as unknown as number[];
        } else if (typeof menu.meals === 'string') {
            try {
                const parsed = JSON.parse(menu.meals);
                if (Array.isArray(parsed)) mealIds = parsed;
            } catch (e) {
                mealIds = [];
            }
        }

        // Filtrar refeições que estão dentro do intervalo calculado
        const mealDateFilter: any = {
            [Op.gte]: mealDateStart,
            [Op.lte]: mealDateEnd
        };
        
        // Para nursing homes, buscar todas as refeições dentro do intervalo que pertencem a menus com menuTypeId = 2
        // Para schools, usar apenas as refeições do array menu.meals
        let meals;
        if (menuTypeId === 2) {
            // Nursing Home: buscar todos os menus com menuTypeId = 2 que se sobrepõem com o intervalo
            // e depois buscar todas as refeições que estão nesses menus
            const nursingHomeMenus = await Menu.findAll({
                where: {
                    menuTypeId: 2,
                    initialDate: {
                        [Op.lte]: mealDateEnd,
                    },
                    finalDate: {
                        [Op.gte]: mealDateStart,
                    }
                }
            });
            
            // Coletar todos os mealIds de todos os menus de nursing home
            const allNursingHomeMealIds = new Set<number>();
            for (const nhMenu of nursingHomeMenus) {
                let nhMealIds: number[] = [];
                if (Array.isArray(nhMenu.meals)) {
                    nhMealIds = nhMenu.meals as unknown as number[];
                } else if (typeof nhMenu.meals === 'string') {
                    try {
                        const parsed = JSON.parse(nhMenu.meals);
                        if (Array.isArray(parsed)) nhMealIds = parsed;
                    } catch (e) {
                        nhMealIds = [];
                    }
                }
                nhMealIds.forEach(id => allNursingHomeMealIds.add(id));
            }
            
            // Buscar refeições que estão nos menus de nursing home e dentro do intervalo de datas
            meals = await Meal.findAll({ 
                where: { 
                    id: Array.from(allNursingHomeMealIds),
                    date: mealDateFilter
                }, 
                order: [["date", "ASC"]] 
            });
        } else {
            // School: usar apenas refeições do array menu.meals
            meals = await Meal.findAll({ 
                where: { 
                    id: mealIds.length > 0 ? mealIds : [-1],
                    date: mealDateFilter
                }, 
                order: [["date", "ASC"]] 
            });
        }

        // Se não houver refeições para a semana navegada, retornar erro
        if (meals.length === 0) {
            throw new Error("MENU_NOT_FOUND");
        }

        // batch fetch related data (dishes, recipes, ingredients, products)
        const dishIds = Array.from(new Set(meals.map(m => m.dishId)));
        const dishes = await Dish.findAll({ where: { id: dishIds } });
        const dishMap = new Map<number, any>();
        const dishTypeIds = new Set<number>();
        for (const d of dishes) {
            dishMap.set(d.id, d);
            if ((d as any).dishTypeId) dishTypeIds.add((d as any).dishTypeId);
        }

        const dishTypeMap = new Map<number, any>();
        if (dishTypeIds.size) {
            const dTypes = await DishType.findAll({ where: { id: Array.from(dishTypeIds) } });
            for (const dt of dTypes) dishTypeMap.set(dt.id, dt.name);
        }

        const recipeIds = Array.from(new Set(dishes.map((d: any) => d.recipeId).filter(Boolean)));
        const recipes = recipeIds.length ? await Recipe.findAll({ where: { id: recipeIds } }) : [];
        const recipeMap = new Map<number, any>();
        for (const r of recipes) recipeMap.set(r.id, r);

        // collect ingredient ids and later product ids
        const ingredientIds = new Set<number>();
        for (const r of recipes) {
            if (Array.isArray((r as any).ingredients)) {
                for (const ingId of (r as any).ingredients as number[]) ingredientIds.add(ingId);
            }
        }

        const ingredients = ingredientIds.size ? await Ingredient.findAll({ where: { id: Array.from(ingredientIds) } }) : [];
        const ingredientMap = new Map<number, any>();
        const productIds = new Set<number>();
        for (const ing of ingredients) {
            ingredientMap.set(ing.id, ing);
            if ((ing as any).productId) productIds.add((ing as any).productId);
        }

        const products = productIds.size ? await Product.findAll({ where: { id: Array.from(productIds) } }) : [];
        const productMap = new Map<number, any>();
        for (const p of products) productMap.set(p.id, p);

        // preload nutrition types map (capture name and optional unitId if present in DB)
        const nutritionTypes = await NutritionType.findAll();
        const nutritionTypeInfoById = new Map<number, { name: string; unitId?: number }>();
        for (const nt of nutritionTypes) {
            const rec: any = nt;
            const info: { name: string; unitId?: number } = { name: rec.name };
            if (typeof rec.unitId === 'number') info.unitId = rec.unitId;
            nutritionTypeInfoById.set(rec.id, info);
        }

    // collect all allergen ids (numeric) and raw allergen names from products and preload names
        const allergenIds = new Set<number>();
        const rawAllergenNames = new Set<string>();
        for (const p of products) {
            let raw = (p as any).allergens;
            // if stored as JSON string, try parse
            if (typeof raw === 'string') {
                try {
                    raw = JSON.parse(raw);
                } catch (e) {
                    // keep as string
                }
            }
            if (!raw) continue;
            if (Array.isArray(raw)) {
                for (const a of raw) {
                    if (typeof a === 'number') {
                        allergenIds.add(a);
                    } else if (typeof a === 'string') {
                        const num = Number(a);
                        if (!Number.isNaN(num)) allergenIds.add(num);
                        else rawAllergenNames.add(a);
                    } else if (a && typeof a === 'object') {
                        if (typeof a.id === 'number') allergenIds.add(a.id);
                        else if (typeof a.id === 'string' && !Number.isNaN(Number(a.id))) allergenIds.add(Number(a.id));
                        else if (a.name) rawAllergenNames.add(a.name);
                    }
                }
            }
        }
        const allergenMap = new Map<number, string>();
        if (allergenIds.size) {
            const allergens = await Allergen.findAll({ where: { id: Array.from(allergenIds) } });
            for (const a of allergens) allergenMap.set(a.id, a.name);
        }

        // preload units map to interpret ingredient quantities
        const units = await Unit.findAll();
        const unitById = new Map<number, string>();
        for (const u of units) unitById.set((u as any).id, (u as any).name);

        // build days structure
        const daysMap: Record<string, { date: Date; meals: any[] }> = {};
        for (const meal of meals) {
            const dish = dishMap.get(meal.dishId) as any;
            const recipe = dish ? recipeMap.get(dish.recipeId) : null;

            // gather allergens and aggregated nutrition
            const allergenNames = new Set<string>();
            const nutritionAgg = new Map<number, number>();

            if (recipe && Array.isArray((recipe as any).ingredients)) {
                for (const ingId of (recipe as any).ingredients as number[]) {
                    const ing = ingredientMap.get(ingId) as any;
                    if (!ing) continue;
                    const prod = productMap.get(ing.productId) as any;
                    if (!prod) continue;

                    // allergens
                            // normalize allergens field (could be JSON string, array of ids, strings or objects)
                            let rawAll = prod.allergens;
                            if (typeof rawAll === 'string') {
                                try { rawAll = JSON.parse(rawAll); } catch (e) { /* leave as string */ }
                            }
                            if (Array.isArray(rawAll)) {
                                for (const a of rawAll as any[]) {
                                    if (typeof a === 'number') {
                                        let aName = allergenMap.get(a);
                                        if (!aName) {
                                            const aRec = await Allergen.findByPk(a);
                                            if (aRec) {
                                                aName = aRec.name;
                                                allergenMap.set(aRec.id, aRec.name);
                                            }
                                        }
                                        if (aName) allergenNames.add(aName);
                                    } else if (typeof a === 'string') {
                                        const num = Number(a);
                                        if (!Number.isNaN(num)) {
                                            let aName = allergenMap.get(num);
                                            if (!aName) {
                                                const aRec = await Allergen.findByPk(num);
                                                if (aRec) {
                                                    aName = aRec.name;
                                                    allergenMap.set(aRec.id, aRec.name);
                                                }
                                            }
                                            if (aName) allergenNames.add(aName);
                                        } else {
                                            allergenNames.add(a);
                                        }
                                    } else if (a && typeof a === 'object') {
                                        if (a.name) allergenNames.add(a.name);
                                        else if (typeof a.id === 'number') {
                                            let aName = allergenMap.get(a.id);
                                            if (!aName) {
                                                const aRec = await Allergen.findByPk(a.id);
                                                if (aRec) {
                                                    aName = aRec.name;
                                                    allergenMap.set(aRec.id, aRec.name);
                                                }
                                            }
                                            if (aName) allergenNames.add(aName);
                                        } else if (typeof a.id === 'string' && !Number.isNaN(Number(a.id))) {
                                            const nid = Number(a.id);
                                            let aName = allergenMap.get(nid);
                                            if (!aName) {
                                                const aRec = await Allergen.findByPk(nid);
                                                if (aRec) {
                                                    aName = aRec.name;
                                                    allergenMap.set(aRec.id, aRec.name);
                                                }
                                            }
                                            if (aName) allergenNames.add(aName);
                                        }
                                    }
                                }
                            } else if (typeof rawAll === 'string') {
                                // single string allergen name
                                allergenNames.add(rawAll);
                            }

                    // nutrition entries
                    // Normalize nutrition field: may be JSON string or array with string numbers
                    let rawNut = prod.nutrition;
                    if (typeof rawNut === 'string') {
                        try { rawNut = JSON.parse(rawNut); } catch (e) { rawNut = null; }
                    }

                    // determine ingredient mass in grams (if possible)
                    let ingredientGrams: number | null = null;
                    const unitName = unitById.get(ing.unitId) || null;
                    if (unitName === 'g') {
                        ingredientGrams = Number(ing.quantity) || null;
                    } else if (unitName === 'kg') {
                        ingredientGrams = (Number(ing.quantity) || 0) * 1000;
                    } else if (unitName === 'mL' || unitName === 'L') {
                        // cannot reliably convert volume to mass without density; skip
                        ingredientGrams = null;
                    } else {
                        // unit is 'unit', 'box' or unknown - skip (no reliable conversion)
                        ingredientGrams = null;
                    }

                    if (Array.isArray(rawNut) && ingredientGrams && ingredientGrams > 0) {
                        for (const n of rawNut as any[]) {
                            let typeId: number | null = null;
                            if (typeof n?.typeId === 'number') typeId = n.typeId;
                            else if (typeof n?.typeId === 'string' && !Number.isNaN(Number(n.typeId))) typeId = Number(n.typeId);

                            const pct = typeof n?.percentage === 'number' ? n.percentage : (typeof n?.percentage === 'string' && !Number.isNaN(Number(n.percentage)) ? Number(n.percentage) : 0);
                            if (typeId !== null) {
                                // product percentages are per 100g
                                const gramsOfNutrient = (pct * ingredientGrams) / 100;
                                const current = nutritionAgg.get(typeId) || 0;
                                nutritionAgg.set(typeId, current + gramsOfNutrient);
                            }
                        }
                    }
                }
            }

            // compute total grams considered (from ingredients where conversion available)
            let totalGrams = 0;
            if (recipe && Array.isArray((recipe as any).ingredients)) {
                for (const ingId of (recipe as any).ingredients as number[]) {
                    const ing = ingredientMap.get(ingId) as any;
                    if (!ing) continue;
                    const unitName = unitById.get(ing.unitId) || null;
                    if (unitName === 'g') totalGrams += Number(ing.quantity) || 0;
                    else if (unitName === 'kg') totalGrams += (Number(ing.quantity) || 0) * 1000;
                }
            }

            const nutrition = [] as any[];
            for (const [typeId, totalGramsOfNutrient] of Array.from(nutritionAgg.entries())) {
                const info = nutritionTypeInfoById.get(typeId) || null;
                let name = info ? info.name : null;
                // try fallback lookup
                if (!name) {
                    const ntRec = await NutritionType.findByPk(typeId);
                    if (ntRec) {
                        name = (ntRec as any).name;
                        nutritionTypeInfoById.set(ntRec.id, { name: (ntRec as any).name, unitId: (ntRec as any).unitId });
                    }
                }

                const grams = totalGramsOfNutrient; // already summed in grams
                const unitIdForType = info?.unitId || (info === null ? undefined : info.unitId);
                const unitNameForType = unitIdForType ? unitById.get(unitIdForType) : null;

                // convert grams to the nutrition type unit if necessary
                let valueInUnit: number | null = null;
                if (unitNameForType === 'g' || unitNameForType === 'gram' || !unitNameForType) {
                    // default to grams
                    valueInUnit = grams;
                } else if (unitNameForType === 'kg') {
                    valueInUnit = grams / 1000;
                } else if (unitNameForType === 'mg') {
                    valueInUnit = grams * 1000;
                } else {
                    // unknown unit mapping: keep grams as fallback
                    valueInUnit = grams;
                }

                const percentageOfMeal = totalGrams > 0 ? (grams / totalGrams) * 100 : null;
                nutrition.push({ typeId, name, unitId: unitIdForType || null, unit: unitNameForType || 'g', value: Number((valueInUnit || 0).toFixed(2)), grams, percentageOfMeal });
            }

            const key = new Date(meal.date).toISOString().split('T')[0];
            if (!daysMap[key]) daysMap[key] = { date: new Date(meal.date), meals: [] };
            const mealEntry: any = {
                id: meal.id,
                name: meal.name,
                mealTypeId: meal.mealTypeId,
                dishId: meal.dishId,
                dishName: dish?.name || null,
                type: dish ? dishTypeMap.get(dish.dishTypeId) : null,
                allergens: Array.from(allergenNames),
                nutrition
            };

            // no debug payload by default

            daysMap[key].meals.push(mealEntry);
        }

        const days = Object.values(daysMap).sort((a, b) => a.date.getTime() - b.date.getTime());

        return { id: menu.id, initialDate: menu.initialDate, finalDate: menu.finalDate, days };
    }

    async updateMenuStatus(id: number, status: "published" | "aproved" | "pending") {
        const menu = await Menu.findByPk(id);
        if (!menu) throw new Error("MENU_NOT_FOUND");
        menu.status = status;
        await menu.save();
        return menu;
    }

    async getMenusByCanteen(canteenId: number) {
        const menus = await Menu.findAll({ where: { canteenId } });
        return menus;
    }
}

import { NeededProduct } from "../Model/NeededProduct";

export class NeededProductService {
    static async create(
        date: Date,
        productId: number,
        mealId: number,
        unit: String,
        quantity: number,
        canteenId: number
    ) {
        return await NeededProduct.create({
            date,
            productId,
            mealId,
            unit,
            quantity,
            canteenId,
            status: "needed"
        });
    }

    static async update(
        id: number,
        data: Partial<{
            date: Date;
            productId: number;
            unit: String;
            quantity: number;
            canteenId: number;
        }>
    ) {
        const neededProduct = await NeededProduct.findByPk(id);
        if (!neededProduct) {
            throw new Error("NeededProduct not found");
        }

        return await neededProduct.update(data);
    }

    static async delete(id: number) {
        const neededProduct = await NeededProduct.findByPk(id);
        if (!neededProduct) {
            throw new Error("NeededProduct not found");
        }

        await neededProduct.destroy();
        return true;
    }
}

import { Order, OrderStatus } from "../Model/Order";
import { Product } from "../Model/Product";
import { User } from "../Model/User";
import { Notification } from "../Model/Notification";

export class OrderService {
    static async create(
        userId: number,
        neededProductId: number,
        productId: number,
        unit: String,
        quantity: number,
        date: Date,
        canteenId: number
    ) {
        return await Order.create({
            userId,
            neededProductId,
            productId,
            unit,
            quantity,
            status: "pending",
            date,
            canteenId
        });
    }

    static async update(
        id: number,
        data: Partial<{
            neededProductId: number;
            productId: number;
            unit: String;
            quantity: number;
        }>
    ) {
        const order = await Order.findByPk(id);
        if (!order) {
            throw new Error("Order not found");
        }

        return await order.update(data);
    }

    static async updateStatus(id: number, status: OrderStatus) {
        const order = await Order.findByPk(id);
        if (!order) {
            throw new Error("Order not found");
        }

        order.status = status;
        await order.save();

        if (status === "rejected") {
        const product = await Product.findByPk(order.productId);
        const user = await User.findByPk(order.userId);
        Notification.create({
            userId: order.userId,
            title: "Encomenda Recusada",
            body: `A encomenda de produto ${product?.name} para dia ${order.date} do produtor ${user?.name} foi recusada.`,
        });
    }
        return order;
    }

    static async delete(id: number) {
        const order = await Order.findByPk(id);
        if (!order) {
            throw new Error("Order not found");
        }

        await order.destroy();
        return true;
    }

    static async getByUserId(userId: number) {
        return await Order.findAll({
            where: { userId }
        });
    }

    static async getAll() {
        return await Order.findAll();
    }
}

import { Reservation } from "../Model/Reservation";
import { Meal } from "../Model/Meal";
import { Dish } from "../Model/Dish";
import { DishType } from "../Model/DishType";
import { Op } from "sequelize";

export class PerformanceService {
    /**
     * Calcula a percentagem de desperdício baseado nas reservas
     * Percentagem = (not consumed / (consumed + not consumed)) * 100
     */
    async calculateWastePercentage(filter?: {
        date?: Date; // Data específica
        period?: "day" | "week" | "month" | "year"; // Período: dia, semana, mês, ano
        dishTypeId?: number; // ID do tipo de prato (peixe, carne, etc)
        mealTypeId?: number; // ID do tipo de refeição (1=Almoço, 2=Jantar)
        dateRangeStart?: Date; // Data de início do intervalo
        dateRangeEnd?: Date; // Data de fim do intervalo
        dayOfWeek?: number; // 0=Domingo, 1=Segunda, 2=Terça, 3=Quarta, 4=Quinta, 5=Sexta, 6=Sábado
        mealId?: number; // ID da refeição
        refeitorioId?: number; // ID do refeitório (para filtrar por refeitório)
    }) {
        const { Op } = require("sequelize");

        // Construir filtro de data baseado nos parâmetros
        let dateFilter: any = {};

        // Verificar se é filtro por dia da semana com intervalo opcional
        if (filter?.dayOfWeek !== undefined && (filter?.dateRangeStart || filter?.dateRangeEnd)) {
            // Se houver intervalo de datas para filtro por dia da semana, aplicar o intervalo
            const startDate = filter.dateRangeStart ? new Date(filter.dateRangeStart) : null;
            const endDate = filter.dateRangeEnd ? new Date(filter.dateRangeEnd) : null;
            
            if (startDate && endDate) {
                startDate.setHours(0, 0, 0, 0);
                endDate.setHours(23, 59, 59, 999);
                dateFilter = {
                    [Op.gte]: startDate,
                    [Op.lte]: endDate,
                };
            } else if (startDate) {
                startDate.setHours(0, 0, 0, 0);
                dateFilter = {
                    [Op.gte]: startDate,
                };
            } else if (endDate) {
                endDate.setHours(23, 59, 59, 999);
                dateFilter = {
                    [Op.lte]: endDate,
                };
            }
        } else if (filter?.dateRangeStart && filter?.dateRangeEnd) {
            // Verificar se é intervalo de tempo personalizado
            const startDate = new Date(filter.dateRangeStart);
            startDate.setHours(0, 0, 0, 0);
            const endDate = new Date(filter.dateRangeEnd);
            endDate.setHours(23, 59, 59, 999);
            
            dateFilter = {
                [Op.gte]: startDate,
                [Op.lte]: endDate,
            };
        } else if (filter?.date && filter?.period) {
            const targetDate = new Date(filter.date);
            let startDate: Date;
            let endDate: Date;

            if (filter.period === "day") {
                // Filtro por dia
                startDate = new Date(targetDate.getFullYear(), targetDate.getMonth(), targetDate.getDate());
                endDate = new Date(targetDate.getFullYear(), targetDate.getMonth(), targetDate.getDate(), 23, 59, 59, 999);
            } else if (filter.period === "week") {
                // Filtro por semana (segunda a domingo)
                const dayOfWeek = targetDate.getDay();
                const diff = dayOfWeek === 0 ? -6 : 1 - dayOfWeek; // Segunda-feira
                startDate = new Date(targetDate);
                startDate.setDate(targetDate.getDate() + diff);
                startDate.setHours(0, 0, 0, 0);
                
                endDate = new Date(startDate);
                endDate.setDate(startDate.getDate() + 6);
                endDate.setHours(23, 59, 59, 999);
            } else if (filter.period === "month") {
                // Filtro por mês
                startDate = new Date(targetDate.getFullYear(), targetDate.getMonth(), 1);
                endDate = new Date(targetDate.getFullYear(), targetDate.getMonth() + 1, 0, 23, 59, 59, 999);
            } else if (filter.period === "year") {
                // Filtro por ano
                startDate = new Date(targetDate.getFullYear(), 0, 1);
                startDate.setHours(0, 0, 0, 0);
                endDate = new Date(targetDate.getFullYear() + 1, 0, 0, 23, 59, 59, 999);
            } else {
                // Default: dia
                startDate = new Date(targetDate.getFullYear(), targetDate.getMonth(), targetDate.getDate());
                endDate = new Date(targetDate.getFullYear(), targetDate.getMonth(), targetDate.getDate(), 23, 59, 59, 999);
            }
            
            dateFilter = {
                [Op.gte]: startDate,
                [Op.lte]: endDate,
            };
        } else if (filter?.date) {
            // Filtro por data específica (compatibilidade com código antigo)
            const targetDate = new Date(filter.date);
            const startOfDay = new Date(targetDate.getFullYear(), targetDate.getMonth(), targetDate.getDate());
            const endOfDay = new Date(targetDate.getFullYear(), targetDate.getMonth(), targetDate.getDate(), 23, 59, 59, 999);
            
            dateFilter = {
                [Op.gte]: startOfDay,
                [Op.lte]: endOfDay,
            };
        }

        // Buscar todas as reservas com status consumed ou not consumed
        // Filtrar pela data da refeição (Meal.date) e tipo de prato
        const mealIncludeOptions: any = {
            model: Meal,
            as: "meal",
            attributes: ["id", "name", "date", "dishId", "mealTypeId"],
            required: true,
            include: [{
                model: Dish,
                as: "dish",
                attributes: ["id", "name", "dishTypeId"],
                required: true,
                include: [{
                    model: DishType,
                    as: "dishType",
                    attributes: ["id", "name"],
                    required: true,
                }],
            }],
        };

        // Adicionar filtro de data e/ou mealId
        const mealWhere: any = {};
        if (dateFilter && Object.keys(dateFilter).length > 0) {
            mealWhere.date = dateFilter;
        }
        if (filter?.mealId) {
            mealWhere.id = filter.mealId;
        }
        if (Object.keys(mealWhere).length > 0) {
            mealIncludeOptions.where = mealWhere;
        }

        // Adicionar filtro de tipo de prato se especificado
        if (filter?.dishTypeId) {
            // O include do Dish está no primeiro nível do include do Meal
            const dishInclude = mealIncludeOptions.include[0];
            if (dishInclude && dishInclude.model === Dish) {
                if (!dishInclude.where) {
                    dishInclude.where = {};
                }
                dishInclude.where.dishTypeId = filter.dishTypeId;
            }
        }

        // Construir where clause para Reservation
        const reservationWhere: any = {
            status: {
                [Op.in]: ["consumed", "not consumed"],
            },
        };

        // Adicionar filtro por refeitório se especificado
        if (filter?.refeitorioId) {
            reservationWhere.refeitorioId = filter.refeitorioId;
        }

        const reservations = await Reservation.findAll({
            where: reservationWhere,
            include: [mealIncludeOptions],
        });

        console.log(`[PerformanceService] Found ${reservations.length} reservations with consumed/not consumed status`);

        // Agrupar por data para retornar detalhes
        const byDate: Record<string, { served: number; notConsumed: number; percentage: number }> = {};
        
        // Agrupar por refeição para retornar detalhes
        const byMeal: Record<number, { 
            mealId: number; 
            mealName: string; 
            mealDate: string; 
            mealTypeId?: number;
            dishTypeId?: number;
            dishName?: string; 
            served: number; // Total marcadas (consumed + not consumed)
            consumed: number; // Apenas consumidas
            notConsumed: number; 
            percentage: number 
        }> = {};
        
        reservations.forEach((reservation: any) => {
            if (!reservation.meal || !reservation.meal.date) return;
            
            const mealDate = new Date(reservation.meal.date);
            const dateKey = mealDate.toISOString().split('T')[0]; // YYYY-MM-DD
            const mealId = reservation.meal.id;
            
            // Agrupar por data
            if (!byDate[dateKey]) {
                byDate[dateKey] = { served: 0, notConsumed: 0, percentage: 0 };
            }
            
            // Agrupar por refeição
            if (!byMeal[mealId]) {
                const mealDateStr = mealDate.toISOString();
                byMeal[mealId] = {
                    mealId: mealId,
                    mealName: reservation.meal.name || `Refeição ID: ${mealId}`,
                    mealDate: mealDateStr,
                    mealTypeId: reservation.meal.mealTypeId,
                    dishTypeId: reservation.meal.dish?.dishTypeId,
                    dishName: reservation.meal.dish?.name,
                    served: 0, // Total marcadas
                    consumed: 0, // Apenas consumidas
                    notConsumed: 0,
                    percentage: 0,
                };
            }
            
            const quantity = reservation.quantity || 1;
            
            if (reservation.status === "consumed") {
                byDate[dateKey].served += quantity;
                byMeal[mealId].served += quantity;
                byMeal[mealId].consumed += quantity;
            } else if (reservation.status === "not consumed") {
                byDate[dateKey].served += quantity;
                byDate[dateKey].notConsumed += quantity;
                byMeal[mealId].served += quantity;
                byMeal[mealId].notConsumed += quantity;
            }
        });

        // Calcular totais
        let totalServed = 0; // consumed + not consumed
        let totalNotConsumed = 0; // not consumed

        reservations.forEach((reservation: any) => {
            if (!reservation.meal) {
                console.log(`[PerformanceService] Reservation ${reservation.id} has no meal`);
                return;
            }
            
            const quantity = reservation.quantity || 1;
            
            if (reservation.status === "consumed") {
                totalServed += quantity;
            } else if (reservation.status === "not consumed") {
                totalServed += quantity;
                totalNotConsumed += quantity;
            }
        });

        console.log(`[PerformanceService] Total served: ${totalServed}, Total not consumed: ${totalNotConsumed}`);

        // Calcular percentagem
        const wastePercentage = totalServed > 0 
            ? (totalNotConsumed / totalServed) * 100 
            : 0;

        // Calcular percentagem por data
        Object.keys(byDate).forEach((dateKey) => {
            const data = byDate[dateKey];
            data.percentage = data.served > 0 ? (data.notConsumed / data.served) * 100 : 0;
        });

        // Calcular percentagem por refeição
        Object.values(byMeal).forEach((mealData) => {
            mealData.percentage = mealData.served > 0 ? (mealData.notConsumed / mealData.served) * 100 : 0;
        });

        // Filtrar byDate e byMeal baseado no filtro de período
        let filteredByDate = Object.entries(byDate);
        let filteredByMeal = Object.values(byMeal);
        
        if (filter?.dayOfWeek !== undefined) {
            // Filtro por dia da semana recorrente
            const targetDayOfWeek = filter.dayOfWeek;
            const rangeStart = filter.dateRangeStart ? new Date(filter.dateRangeStart) : null;
            const rangeEnd = filter.dateRangeEnd ? new Date(filter.dateRangeEnd) : null;
            
            // Filtrar byDate
            filteredByDate = filteredByDate.filter(([dateKey]) => {
                const date = new Date(dateKey);
                const dayOfWeek = date.getDay(); // 0=Domingo, 1=Segunda, etc.
                
                // Verificar se o dia da semana corresponde
                if (dayOfWeek !== targetDayOfWeek) {
                    return false;
                }
                
                // Se houver intervalo de datas, verificar se está dentro do intervalo
                if (rangeStart || rangeEnd) {
                    date.setHours(0, 0, 0, 0);
                    if (rangeStart) {
                        rangeStart.setHours(0, 0, 0, 0);
                        if (date < rangeStart) return false;
                    }
                    if (rangeEnd) {
                        rangeEnd.setHours(23, 59, 59, 999);
                        if (date > rangeEnd) return false;
                    }
                }
                
                return true;
            });
            
            // Filtrar byMeal pelo mesmo critério
            if (rangeStart && rangeEnd) {
                filteredByMeal = filteredByMeal.filter((mealData) => {
                    const mealDate = new Date(mealData.mealDate);
                    const dayOfWeek = mealDate.getDay();
                    
                    // Verificar se o dia da semana corresponde
                    if (dayOfWeek !== targetDayOfWeek) {
                        return false;
                    }
                    
                    // Verificar se está dentro do intervalo
                    mealDate.setHours(0, 0, 0, 0);
                    const start = new Date(rangeStart);
                    start.setHours(0, 0, 0, 0);
                    const end = new Date(rangeEnd);
                    end.setHours(23, 59, 59, 999);
                    
                    return mealDate >= start && mealDate <= end;
                });
            }
        } else if (filter?.dateRangeStart && filter?.dateRangeEnd) {
            // Se for filtro por intervalo de tempo, mostrar apenas os dias no intervalo
            const rangeStart = new Date(filter.dateRangeStart);
            rangeStart.setHours(0, 0, 0, 0);
            const rangeEnd = new Date(filter.dateRangeEnd);
            rangeEnd.setHours(23, 59, 59, 999);
            
            filteredByDate = filteredByDate.filter(([dateKey]) => {
                const date = new Date(dateKey);
                date.setHours(0, 0, 0, 0);
                return date >= rangeStart && date <= rangeEnd;
            });
        } else if (filter?.period === "day" && filter?.date) {
            // Se for filtro por dia, mostrar apenas esse dia
            const targetDate = new Date(filter.date);
            const targetDateStr = targetDate.toISOString().split('T')[0];
            filteredByDate = filteredByDate.filter(([dateKey]) => dateKey === targetDateStr);
        } else if (filter?.period === "week" && filter?.date) {
            // Se for filtro por semana, mostrar apenas os dias da semana
            const targetDate = new Date(filter.date);
            const dayOfWeek = targetDate.getDay();
            const diff = dayOfWeek === 0 ? -6 : 1 - dayOfWeek; // Segunda-feira
            const weekStart = new Date(targetDate);
            weekStart.setDate(targetDate.getDate() + diff);
            weekStart.setHours(0, 0, 0, 0);
            
            const weekEnd = new Date(weekStart);
            weekEnd.setDate(weekStart.getDate() + 6);
            weekEnd.setHours(23, 59, 59, 999);
            
            filteredByDate = filteredByDate.filter(([dateKey]) => {
                const date = new Date(dateKey);
                return date >= weekStart && date <= weekEnd;
            });
        } else if (filter?.period === "month" && filter?.date) {
            // Se for filtro por mês, mostrar apenas os dias do mês
            const targetDate = new Date(filter.date);
            const monthStart = new Date(targetDate.getFullYear(), targetDate.getMonth(), 1);
            const monthEnd = new Date(targetDate.getFullYear(), targetDate.getMonth() + 1, 0, 23, 59, 59, 999);
            
            filteredByDate = filteredByDate.filter(([dateKey]) => {
                const date = new Date(dateKey);
                return date >= monthStart && date <= monthEnd;
            });
        } else if (filter?.period === "year" && filter?.date) {
            // Se for filtro por ano, mostrar apenas os dias do ano
            const targetDate = new Date(filter.date);
            const yearStart = new Date(targetDate.getFullYear(), 0, 1);
            yearStart.setHours(0, 0, 0, 0);
            const yearEnd = new Date(targetDate.getFullYear() + 1, 0, 0, 23, 59, 59, 999);
            
            filteredByDate = filteredByDate.filter(([dateKey]) => {
                const date = new Date(dateKey);
                date.setHours(0, 0, 0, 0);
                return date >= yearStart && date <= yearEnd;
            });
        }

        // Filtrar byMeal baseado no filtro de data (se ainda não foi filtrado por dayOfWeek)
        if (filter?.dayOfWeek === undefined) {
            filteredByMeal = Object.values(byMeal);
        }
        
        if (filter?.period === "day" && filter?.date) {
            // Se for filtro por dia, mostrar apenas refeições desse dia
            const targetDate = new Date(filter.date);
            const targetDateStr = targetDate.toISOString().split('T')[0];
            filteredByMeal = filteredByMeal.filter((mealData) => {
                const mealDate = new Date(mealData.mealDate);
                const mealDateStr = mealDate.toISOString().split('T')[0];
                return mealDateStr === targetDateStr;
            });
        } else if (filter?.dateRangeStart && filter?.dateRangeEnd) {
            // Se for filtro por intervalo, mostrar apenas refeições no intervalo
            const rangeStart = new Date(filter.dateRangeStart);
            rangeStart.setHours(0, 0, 0, 0);
            const rangeEnd = new Date(filter.dateRangeEnd);
            rangeEnd.setHours(23, 59, 59, 999);
            
            filteredByMeal = filteredByMeal.filter((mealData) => {
                const mealDate = new Date(mealData.mealDate);
                return mealDate >= rangeStart && mealDate <= rangeEnd;
            });
        } else if (filter?.date && filter?.period === "week") {
            // Se for filtro por semana, mostrar apenas refeições da semana
            const targetDate = new Date(filter.date);
            const dayOfWeek = targetDate.getDay();
            const diff = dayOfWeek === 0 ? -6 : 1 - dayOfWeek;
            const weekStart = new Date(targetDate);
            weekStart.setDate(targetDate.getDate() + diff);
            weekStart.setHours(0, 0, 0, 0);
            const weekEnd = new Date(weekStart);
            weekEnd.setDate(weekStart.getDate() + 6);
            weekEnd.setHours(23, 59, 59, 999);
            
            filteredByMeal = filteredByMeal.filter((mealData) => {
                const mealDate = new Date(mealData.mealDate);
                return mealDate >= weekStart && mealDate <= weekEnd;
            });
        } else if (filter?.date && filter?.period === "month") {
            // Se for filtro por mês, mostrar apenas refeições do mês
            const targetDate = new Date(filter.date);
            const monthStart = new Date(targetDate.getFullYear(), targetDate.getMonth(), 1);
            const monthEnd = new Date(targetDate.getFullYear(), targetDate.getMonth() + 1, 0, 23, 59, 59, 999);
            
            filteredByMeal = filteredByMeal.filter((mealData) => {
                const mealDate = new Date(mealData.mealDate);
                return mealDate >= monthStart && mealDate <= monthEnd;
            });
        }

        // Recalcular totais com base nos dados filtrados
        // Isso garante que os totais reflitam apenas o período filtrado
        let recalculatedTotalServed = 0;
        let recalculatedTotalNotConsumed = 0;
        
        filteredByDate.forEach(([dateKey, data]) => {
            recalculatedTotalServed += data.served;
            recalculatedTotalNotConsumed += data.notConsumed;
        });
        
        // Calcular percentagem com base nos totais recalculados
        const recalculatedWastePercentage = recalculatedTotalServed > 0 
            ? (recalculatedTotalNotConsumed / recalculatedTotalServed) * 100 
            : 0;

        return {
            totalServed: recalculatedTotalServed,
            totalNotConsumed: recalculatedTotalNotConsumed,
            wastePercentage: Number(recalculatedWastePercentage.toFixed(2)),
            byDate: filteredByDate
                .map(([date, data]) => ({
                    date,
                    served: data.served,
                    notConsumed: data.notConsumed,
                    percentage: Number(data.percentage.toFixed(2)),
                }))
                .sort((a, b) => a.date.localeCompare(b.date)),
            byMeal: filteredByMeal
                .map((mealData) => ({
                    mealId: mealData.mealId,
                    mealName: mealData.mealName,
                    mealDate: mealData.mealDate,
                    mealTypeId: mealData.mealTypeId,
                    dishTypeId: mealData.dishTypeId,
                    dishName: mealData.dishName,
                    served: mealData.served, // Total marcadas
                    consumed: mealData.consumed, // Apenas consumidas
                    notConsumed: mealData.notConsumed,
                    percentage: Number(mealData.percentage.toFixed(2)),
                }))
                .sort((a, b) => new Date(a.mealDate).getTime() - new Date(b.mealDate).getTime()),
        };
    }
}

import { User } from "../Model/User";
import { Application } from "../Model/Application";
import { FarmerProduct } from "../Model/FarmerProducts";
import { Product } from "../Model/Product";
import { Order } from "../Model/Order";
import { Canteen } from "../Model/Canteen";

export interface ProducerStatistics {
    totalProducers: number;
    totalApplications: number;
    approvalRate: number;
    producersByStatus: {
        approved: number;
        submitted: number;
        under_review: number;
        rejected: number;
        cancelled: number;
    };
    topProducers: Array<{
        userId: number;
        userName: string;
        email: string;
        totalQuantity: number;
        productCount: number;
        applicationStatus: string;
    }>;
    topProducts: Array<{
        productId: number;
        productName: string;
        totalQuantity: number;
        unit: string;
        producerCount: number;
    }>;
    ordersByCanteen: Array<{
        canteenId: number;
        canteenName: string;
        totalOrders: number;
        ordersByStatus: {
            pending: number;
            sent: number;
            confirmed: number;
            rejected: number;
            cancelled: number;
            delivered: number;
        };
        quantitiesByUnit: Array<{
            unit: string;
            totalQuantity: number;
        }>;
        lastDeliveryDate: string | null;
        lastOrderDate: string | null;
        lastPendingDate: string | null;
        products: Array<{
            productId: number;
            productName: string;
            quantity: number;
            unit: string;
            status: string;
        }>;
    }>;
    totalOrders: number;
    deliveredProducts: Array<{
        productId: number;
        productName: string;
        totalQuantity: number;
        unit: string;
        orderCount: number;
    }>;
    deliveryStats: {
        deliveryRate: number;
        averageQuantityByUnit: Array<{
            unit: string;
            averageQuantity: number;
        }>;
        uniqueProductsDelivered: number;
    };
}

export class ProducerStatisticsService {
    async getProducerStatistics(filters?: { producerId?: number }): Promise<ProducerStatistics> {
        // 1. Total de produtores
        const totalProducers = await User.count({
            where: { role: "Supplier" }
        });

        // 2. Total de candidaturas
        const applicationsQuery: any = {};
        if (filters?.producerId) {
            applicationsQuery.userId = filters.producerId;
        }

        const applications = await Application.findAll({
            where: applicationsQuery
        });

        const totalApplications = applications.length;

        // 3. Distribuição por status
        const producersByStatus = {
            approved: 0,
            submitted: 0,
            under_review: 0,
            rejected: 0,
            cancelled: 0
        };

        applications.forEach(app => {
            if (app.status in producersByStatus) {
                producersByStatus[app.status as keyof typeof producersByStatus]++;
            }
        });

        // 4. Taxa de aprovação
        const approvedCount = producersByStatus.approved;
        const approvalRate = totalApplications > 0 
            ? (approvedCount / totalApplications) * 100 
            : 0;

        // 5. Top produtores por quantidade oferecida
        const farmerProductsQuery: any = {};
        if (filters?.producerId) {
            farmerProductsQuery.userId = filters.producerId;
        }

        const farmerProducts = await FarmerProduct.findAll({
            where: farmerProductsQuery,
            include: [
                { model: User, as: "user", attributes: ["id", "name", "email"] },
                { model: Product, as: "product", attributes: ["id", "name"] }
            ]
        });

        // Agrupar por produtor
        const producerMap = new Map<number, {
            name: string;
            email: string;
            totalQuantity: number;
            productIds: Set<number>;
            applicationStatus: string;
        }>();

        farmerProducts.forEach(fp => {
            const userId = fp.userId;
            const fpData = fp as any;
            const userName = fpData.user?.name || `Produtor ${userId}`;
            const userEmail = fpData.user?.email || "";
            const application = applications.find(app => app.userId === userId);
            const status = application?.status || "no_application";

            if (!producerMap.has(userId)) {
                producerMap.set(userId, {
                    name: userName,
                    email: userEmail,
                    totalQuantity: 0,
                    productIds: new Set(),
                    applicationStatus: status
                });
            }

            const producerData = producerMap.get(userId)!;
            producerData.totalQuantity += fp.quantity;
            producerData.productIds.add(fp.productId);
        });

        const topProducers = Array.from(producerMap.entries())
            .map(([userId, data]) => ({
                userId,
                userName: data.name,
                email: data.email,
                totalQuantity: data.totalQuantity,
                productCount: data.productIds.size,
                applicationStatus: data.applicationStatus
            }))
            .sort((a, b) => b.totalQuantity - a.totalQuantity)
            .slice(0, 5); // Top 5

        // 6. Top produtos mais oferecidos
        const productMap = new Map<number, {
            name: string;
            totalQuantity: number;
            unit: string;
            producerIds: Set<number>;
        }>();
        
        farmerProducts.forEach(fp => {
            const productId = fp.productId;
            const fpData = fp as any;
            const productName = fpData.product?.name || `Produto ${productId}`;
            const unit = fp.unit;
            const userId = fp.userId;

            if (!productMap.has(productId)) {
                productMap.set(productId, {
                    name: productName,
                    totalQuantity: 0,
                    unit: unit,
                    producerIds: new Set()
                });
            }

            const productData = productMap.get(productId)!;
            productData.totalQuantity += fp.quantity;
            productData.producerIds.add(userId);
        });

        const topProducts = Array.from(productMap.entries())
            .map(([productId, data]) => ({
                productId,
                productName: data.name,
                totalQuantity: data.totalQuantity,
                unit: data.unit,
                producerCount: data.producerIds.size
            }))
            .sort((a, b) => b.totalQuantity - a.totalQuantity)
            .slice(0, 10); // Top 10

        // 7. Estatísticas de Orders por Cantina
        const allOrders = await Order.findAll({
            include: [
                { model: Canteen, as: "canteen", attributes: ["id", "name"] },
                { model: Product, as: "product", attributes: ["id", "name"] }
            ]
        });

        const totalOrders = allOrders.length;

        const canteenMap = new Map<number, {
            canteenName: string;
            orders: Order[];
        }>();

        allOrders.forEach(order => {
            const canteenId = order.canteenId;
            const orderData = order as any;
            const canteenName = orderData.canteen?.name || `Cantina ${canteenId}`;

            if (!canteenMap.has(canteenId)) {
                canteenMap.set(canteenId, {
                    canteenName,
                    orders: []
                });
            }

            canteenMap.get(canteenId)!.orders.push(order);
        });

        const ordersByCanteen = Array.from(canteenMap.entries())
            .map(([canteenId, data]) => {
                const orders = data.orders;
                const ordersByStatus = {
                    pending: 0,
                    sent: 0,
                    confirmed: 0,
                    rejected: 0,
                    cancelled: 0,
                    delivered: 0
                };

                // Agrupar quantidades por unidade e produtos
                const quantitiesByUnitMap = new Map<string, number>();
                const productsList: Array<{
                    productId: number;
                    productName: string;
                    quantity: number;
                    unit: string;
                    status: string;
                }> = [];
                let lastDeliveryDate: string | null = null;
                let lastOrderDate: string | null = null;
                let lastPendingDate: string | null = null;

                orders.forEach(order => {
                    if (order.status in ordersByStatus) {
                        ordersByStatus[order.status as keyof typeof ordersByStatus]++;
                    }
                    
                    // Converter data da order
                    let orderDate: string;
                    const dateValue = order.date as any;
                    if (dateValue instanceof Date) {
                        orderDate = dateValue.toISOString().split('T')[0];
                    } else if (typeof dateValue === 'string') {
                        orderDate = dateValue.split('T')[0];
                    } else {
                        orderDate = String(dateValue).split('T')[0];
                    }
                    
                    // Guardar a data mais recente de qualquer order (para ordenação)
                    if (!lastOrderDate || orderDate > lastOrderDate) {
                        lastOrderDate = orderDate;
                    }
                    
                    // Se a order foi entregue, guardar a data mais recente de entrega
                    if (order.status === "delivered") {
                        if (!lastDeliveryDate || orderDate > lastDeliveryDate) {
                            lastDeliveryDate = orderDate;
                        }
                    }
                    
                    // Se a order está pendente, guardar a data mais recente de pending
                    if (order.status === "pending") {
                        if (!lastPendingDate || orderDate > lastPendingDate) {
                            lastPendingDate = orderDate;
                        }
                    }
                    
                    // Adicionar produto à lista
                    const orderData = order as any;
                    const productName = orderData.product?.name || `Produto ${order.productId}`;
                    productsList.push({
                        productId: order.productId,
                        productName,
                        quantity: order.quantity,
                        unit: order.unit.toString(),
                        status: order.status
                    });
                    
                    const unit = order.unit.toString();
                    if (!quantitiesByUnitMap.has(unit)) {
                        quantitiesByUnitMap.set(unit, 0);
                    }
                    quantitiesByUnitMap.set(unit, quantitiesByUnitMap.get(unit)! + order.quantity);
                });

                const quantitiesByUnit = Array.from(quantitiesByUnitMap.entries())
                    .map(([unit, totalQuantity]) => ({
                        unit,
                        totalQuantity
                    }))
                    .sort((a, b) => b.totalQuantity - a.totalQuantity);

                return {
                    canteenId,
                    canteenName: data.canteenName,
                    totalOrders: orders.length,
                    ordersByStatus,
                    quantitiesByUnit,
                    lastDeliveryDate,
                    lastOrderDate,
                    lastPendingDate,
                    products: productsList
                };
            })
            .sort((a, b) => {
                // Ordenar por data mais recente primeiro (mais recente no topo)
                const dateA = a.lastOrderDate ? String(a.lastOrderDate) : '';
                const dateB = b.lastOrderDate ? String(b.lastOrderDate) : '';
                
                if (dateA && dateB) {
                    return dateB.localeCompare(dateA);
                }
                if (dateA) return -1;
                if (dateB) return 1;
                // Se não houver datas, ordenar por total de orders
                return b.totalOrders - a.totalOrders;
            });

        // 8. Produtos Entregues ordenados por quantidade
        const deliveredOrders = allOrders.filter(order => order.status === "delivered");
        
        const deliveredProductMap = new Map<number, {
            productName: string;
            totalQuantity: number;
            unit: string;
            orderCount: number;
        }>();

        deliveredOrders.forEach(order => {
            const productId = order.productId;
            const orderData = order as any;
            const productName = orderData.product?.name || `Produto ${productId}`;
            const unit = order.unit.toString();

            if (!deliveredProductMap.has(productId)) {
                deliveredProductMap.set(productId, {
                    productName,
                    totalQuantity: 0,
                    unit,
                    orderCount: 0
                });
            }

            const productData = deliveredProductMap.get(productId)!;
            productData.totalQuantity += order.quantity;
            productData.orderCount += 1;
        });

        const deliveredProducts = Array.from(deliveredProductMap.entries())
            .map(([productId, data]) => ({
                productId,
                productName: data.productName,
                totalQuantity: data.totalQuantity,
                unit: data.unit,
                orderCount: data.orderCount
            }))
            .sort((a, b) => b.totalQuantity - a.totalQuantity);

        // Estatísticas de entrega
        const deliveredOrdersCount = deliveredOrders.length;
        const deliveryRate = totalOrders > 0 
            ? (deliveredOrdersCount / totalOrders) * 100 
            : 0;
        
        // Calcular média por unidade (não misturar unidades diferentes)
        const quantityByUnitMap = new Map<string, { total: number; count: number }>();
        deliveredOrders.forEach(order => {
            const unit = order.unit.toString();
            if (!quantityByUnitMap.has(unit)) {
                quantityByUnitMap.set(unit, { total: 0, count: 0 });
            }
            const unitData = quantityByUnitMap.get(unit)!;
            unitData.total += order.quantity;
            unitData.count += 1;
        });
        
        const averageQuantityByUnit = Array.from(quantityByUnitMap.entries())
            .map(([unit, data]) => ({
                unit,
                averageQuantity: data.count > 0 ? data.total / data.count : 0
            }))
            .sort((a, b) => b.averageQuantity - a.averageQuantity);
        
        const uniqueProductsDelivered = deliveredProductMap.size;

        return {
            totalProducers,
            totalApplications,
            approvalRate: Math.round(approvalRate * 100) / 100, // 2 casas decimais
            producersByStatus,
            topProducers,
            topProducts,
            ordersByCanteen,
            totalOrders,
            deliveredProducts,
            deliveryStats: {
                deliveryRate: Math.round(deliveryRate * 100) / 100,
                averageQuantityByUnit,
                uniqueProductsDelivered
            }
        };
    }
}

import { ReservationQuantitiesCanteen } from "../Model/ReservationQuantitiesCanteen";
import { Dish } from "../Model/Dish";
import { Refeitorio } from "../Model/Refeitorio";
import { Canteen } from "../Model/Canteen";
import { Recipe } from "../Model/Recipe";
import { Ingredient } from "../Model/Ingredient";
import { Product } from "../Model/Product";
import { Unit } from "../Model/Unit";
import { DishType } from "../Model/DishType";

// Interface para tipar o resultado do findAll com includes
interface ReservationQuantitiesCanteenWithDish extends ReservationQuantitiesCanteen {
    dish?: Dish & {
        dishType?: DishType;
    };
}

export class ReservationQuantitiesCanteenService {
    async getCanteenProductionStatistics(canteenId: number, filters?: {
        date?: string;
        dateRangeStart?: string;
        dateRangeEnd?: string;
        dishId?: number;
        refeitorioId?: number;
        dishTypeId?: number; // Filtrar por tipo de prato (Carne, Peixe, Vegetariano)
        period?: string; // "day", "week", "month", "year"
        dayOfWeek?: number; // 0=Domingo, 1=Segunda, ..., 6=Sábado
    }) {
        const { Op } = require("sequelize");
        
        const whereClause: any = {
            canteenId: canteenId
        };

        // Filtro por período
        if (filters?.period) {
            if (filters.period === "day" && filters?.date) {
                const filterDate = new Date(filters.date);
                const year = filterDate.getUTCFullYear();
                const month = filterDate.getUTCMonth();
                const day = filterDate.getUTCDate();
                
                const startOfDay = new Date(Date.UTC(year, month, day, 0, 0, 0, 0));
                const endOfDay = new Date(Date.UTC(year, month, day, 23, 59, 59, 999));
                
                whereClause.date = {
                    [Op.between]: [startOfDay, endOfDay]
                };
            } else if (filters.period === "week" && filters?.dateRangeStart && filters?.dateRangeEnd) {
                const startDate = new Date(filters.dateRangeStart);
                startDate.setHours(0, 0, 0, 0);
                const endDate = new Date(filters.dateRangeEnd);
                endDate.setHours(23, 59, 59, 999);
                
                whereClause.date = {
                    [Op.between]: [startDate, endDate]
                };
            } else if (filters.period === "month" && filters?.date) {
                const filterDate = new Date(filters.date);
                const year = filterDate.getUTCFullYear();
                const month = filterDate.getUTCMonth();
                
                const startOfMonth = new Date(Date.UTC(year, month, 1, 0, 0, 0, 0));
                const endOfMonth = new Date(Date.UTC(year, month + 1, 0, 23, 59, 59, 999));
                
                whereClause.date = {
                    [Op.between]: [startOfMonth, endOfMonth]
                };
            } else if (filters.period === "year" && filters?.date) {
                const filterDate = new Date(filters.date);
                const year = filterDate.getUTCFullYear();
                
                const startOfYear = new Date(Date.UTC(year, 0, 1, 0, 0, 0, 0));
                const endOfYear = new Date(Date.UTC(year, 11, 31, 23, 59, 59, 999));
                
                whereClause.date = {
                    [Op.between]: [startOfYear, endOfYear]
                };
            }
        } else if (filters?.date && !filters?.period) {
            // Filtro por data específica (sem período)
            const filterDate = new Date(filters.date);
            const year = filterDate.getUTCFullYear();
            const month = filterDate.getUTCMonth();
            const day = filterDate.getUTCDate();
            
            const startOfDay = new Date(Date.UTC(year, month, day, 0, 0, 0, 0));
            const endOfDay = new Date(Date.UTC(year, month, day, 23, 59, 59, 999));
            
            whereClause.date = {
                [Op.between]: [startOfDay, endOfDay]
            };
        }

        // Filtro por intervalo de datas (sem período)
        if (filters?.dateRangeStart && filters?.dateRangeEnd && !filters?.period) {
            const startDate = new Date(filters.dateRangeStart);
            startDate.setHours(0, 0, 0, 0);
            const endDate = new Date(filters.dateRangeEnd);
            endDate.setHours(23, 59, 59, 999);
            
            whereClause.date = {
                [Op.between]: [startDate, endDate]
            };
        }

        // Filtro por dia da semana (dentro de um intervalo de datas)
        if (filters?.dayOfWeek !== undefined && filters?.dateRangeStart && filters?.dateRangeEnd) {
            // Este filtro será aplicado após buscar os registos, filtrando por dia da semana
            // Por enquanto, vamos buscar todos os registos do intervalo e filtrar depois
        }

        // Filtro por prato
        if (filters?.dishId) {
            whereClause.dishId = filters.dishId;
        }

        // Filtro por refeitório
        if (filters?.refeitorioId) {
            whereClause.refeitorioId = filters.refeitorioId;
        }

        let records = await ReservationQuantitiesCanteen.findAll({
            where: whereClause,
            include: [
                { 
                    model: Dish, 
                    as: "dish", 
                    attributes: ["id", "name", "dishTypeId"],
                    include: [
                        { 
                            model: DishType, 
                            as: "dishType", 
                            attributes: ["id", "name"],
                            required: false
                        }
                    ],
                    where: filters?.dishTypeId ? { dishTypeId: filters.dishTypeId } : undefined,
                    required: filters?.dishTypeId ? true : false
                },
                { model: Refeitorio, as: "refeitorio", attributes: ["id", "name"] },
                { model: Canteen, as: "canteen", attributes: ["id", "name"] }
            ],
            order: [["date", "DESC"], ["dishId", "ASC"]]
        }) as ReservationQuantitiesCanteenWithDish[];

        // Filtro por dia da semana (aplicado após buscar os registos)
        if (filters?.dayOfWeek !== undefined && filters?.dateRangeStart && filters?.dateRangeEnd) {
            records = records.filter(record => {
                const recordDate = new Date(record.date);
                const dayOfWeek = recordDate.getDay(); // 0=Domingo, 1=Segunda, ..., 6=Sábado
                return dayOfWeek === filters.dayOfWeek;
            });
        }

        // Calcular totais
        const totalQuantity = records.reduce((sum, record) => sum + record.quantity, 0);

        return {
            records,
            totalQuantity,
            totalRecords: records.length
        };
    }

    /**
     * Calcula as quantidades de ingredientes produzidos baseado nas quantidades de pratos
     * Multiplica: ingredient.quantity × reservation_quantities_canteen.quantity
     * Agrupa por: dishTypeId, productId, unitId
     */
    async getCanteenIngredientsStatistics(canteenId: number, filters?: {
        date?: string;
        dateRangeStart?: string;
        dateRangeEnd?: string;
        dishId?: number;
        refeitorioId?: number;
        dishTypeId?: number; // Filtrar por tipo de prato (Carne, Peixe, Vegetariano)
        period?: string; // "day", "week", "month", "year"
        dayOfWeek?: number; // 0=Domingo, 1=Segunda, ..., 6=Sábado
    }) {
        const { Op } = require("sequelize");
        
        // Primeiro, buscar os registos de produção (mesma lógica do método anterior)
        const whereClause: any = {
            canteenId: canteenId
        };

        // Aplicar os mesmos filtros de data do método anterior
        if (filters?.period) {
            if (filters.period === "day" && filters?.date) {
                const filterDate = new Date(filters.date);
                const year = filterDate.getUTCFullYear();
                const month = filterDate.getUTCMonth();
                const day = filterDate.getUTCDate();
                
                const startOfDay = new Date(Date.UTC(year, month, day, 0, 0, 0, 0));
                const endOfDay = new Date(Date.UTC(year, month, day, 23, 59, 59, 999));
                
                whereClause.date = {
                    [Op.between]: [startOfDay, endOfDay]
                };
            } else if (filters.period === "week" && filters?.dateRangeStart && filters?.dateRangeEnd) {
                const startDate = new Date(filters.dateRangeStart);
                startDate.setHours(0, 0, 0, 0);
                const endDate = new Date(filters.dateRangeEnd);
                endDate.setHours(23, 59, 59, 999);
                
                whereClause.date = {
                    [Op.between]: [startDate, endDate]
                };
            } else if (filters.period === "month" && filters?.date) {
                const filterDate = new Date(filters.date);
                const year = filterDate.getUTCFullYear();
                const month = filterDate.getUTCMonth();
                
                const startOfMonth = new Date(Date.UTC(year, month, 1, 0, 0, 0, 0));
                const endOfMonth = new Date(Date.UTC(year, month + 1, 0, 23, 59, 59, 999));
                
                whereClause.date = {
                    [Op.between]: [startOfMonth, endOfMonth]
                };
            } else if (filters.period === "year" && filters?.date) {
                const filterDate = new Date(filters.date);
                const year = filterDate.getUTCFullYear();
                
                const startOfYear = new Date(Date.UTC(year, 0, 1, 0, 0, 0, 0));
                const endOfYear = new Date(Date.UTC(year, 11, 31, 23, 59, 59, 999));
                
                whereClause.date = {
                    [Op.between]: [startOfYear, endOfYear]
                };
            }
        } else if (filters?.date && !filters?.period) {
            const filterDate = new Date(filters.date);
            const year = filterDate.getUTCFullYear();
            const month = filterDate.getUTCMonth();
            const day = filterDate.getUTCDate();
            
            const startOfDay = new Date(Date.UTC(year, month, day, 0, 0, 0, 0));
            const endOfDay = new Date(Date.UTC(year, month, day, 23, 59, 59, 999));
            
            whereClause.date = {
                [Op.between]: [startOfDay, endOfDay]
            };
        }

        if (filters?.dateRangeStart && filters?.dateRangeEnd && !filters?.period) {
            const startDate = new Date(filters.dateRangeStart);
            startDate.setHours(0, 0, 0, 0);
            const endDate = new Date(filters.dateRangeEnd);
            endDate.setHours(23, 59, 59, 999);
            
            whereClause.date = {
                [Op.between]: [startDate, endDate]
            };
        }

        if (filters?.dishId) {
            whereClause.dishId = filters.dishId;
        }

        if (filters?.refeitorioId) {
            whereClause.refeitorioId = filters.refeitorioId;
        }

        // Buscar registos de produção com Dish incluído (precisamos do recipeId e dishTypeId)
        let records = await ReservationQuantitiesCanteen.findAll({
            where: whereClause,
            include: [
                { 
                    model: Dish, 
                    as: "dish", 
                    attributes: ["id", "name", "recipeId", "dishTypeId"],
                    include: [
                        { 
                            model: DishType, 
                            as: "dishType", 
                            attributes: ["id", "name"],
                            required: false
                        }
                    ],
                    required: true
                }
            ],
            order: [["date", "DESC"], ["dishId", "ASC"]]
        }) as ReservationQuantitiesCanteenWithDish[];

        // Filtro por dia da semana
        if (filters?.dayOfWeek !== undefined && filters?.dateRangeStart && filters?.dateRangeEnd) {
            records = records.filter(record => {
                const recordDate = new Date(record.date);
                const dayOfWeek = recordDate.getDay();
                return dayOfWeek === filters.dayOfWeek;
            });
        }

        // Agora calcular as quantidades de ingredientes
        // Map para agrupar por: dishTypeId + productId + unitId
        const ingredientsMap = new Map<string, {
            dishTypeId: number;
            dishTypeName: string;
            productId: number;
            productName: string;
            unitId: number;
            unitName: string;
            totalQuantity: number;
        }>();

        // Buscar todos os ingredientes de uma vez (para otimizar)
        const allIngredientIds = new Set<number>();
        const allRecipeIds = new Set<number>();

        for (const record of records) {
            const dish = record.dish;
            if (dish && dish.recipeId) {
                allRecipeIds.add(dish.recipeId);
            }
        }

        // Buscar todas as receitas necessárias
        const recipes = await Recipe.findAll({
            where: {
                id: { [Op.in]: Array.from(allRecipeIds) }
            }
        });

        const recipeMap = new Map(recipes.map(r => [r.id, r]));

        // Coletar todos os IDs de ingredientes
        for (const recipe of recipes) {
            if (Array.isArray(recipe.ingredients)) {
                recipe.ingredients.forEach((ingId: number) => allIngredientIds.add(ingId));
            }
        }

        // Buscar todos os ingredientes de uma vez
        const ingredients = await Ingredient.findAll({
            where: {
                id: { [Op.in]: Array.from(allIngredientIds) }
            },
            include: [
                { model: Product, as: "product", attributes: ["id", "name"] },
                { model: Unit, as: "unit", attributes: ["id", "name"] }
            ]
        });

        const ingredientMap = new Map(ingredients.map(ing => [ing.id, ing]));

        // Processar cada registo de produção
        for (const record of records) {
            const dish = record.dish;
            if (!dish || !dish.recipeId) continue;

            // Filtrar por dishTypeId se especificado
            if (filters?.dishTypeId && dish.dishTypeId !== filters.dishTypeId) {
                continue;
            }

            const recipe = recipeMap.get(dish.recipeId);
            if (!recipe || !Array.isArray(recipe.ingredients)) continue;

            const dishType = dish.dishType;
            const dishTypeId = dish.dishTypeId;
            const dishTypeName = dishType?.name || `Tipo ${dishTypeId}`;

            // Para cada ingrediente na receita
            for (const ingredientId of recipe.ingredients) {
                const ingredient = ingredientMap.get(ingredientId);
                if (!ingredient) continue;

                const product = (ingredient as any).product;
                const unit = (ingredient as any).unit;

                if (!product || !unit) continue;

                // Calcular quantidade total: ingredient.quantity × reservation_quantities_canteen.quantity
                const totalQuantityForThisRecord = ingredient.quantity * record.quantity;

                // Chave para agrupar: dishTypeId + productId + unitId
                const key = `${dishTypeId}_${ingredient.productId}_${ingredient.unitId}`;

                if (ingredientsMap.has(key)) {
                    // Somar à quantidade existente
                    const existing = ingredientsMap.get(key)!;
                    existing.totalQuantity += totalQuantityForThisRecord;
                } else {
                    // Criar nova entrada
                    ingredientsMap.set(key, {
                        dishTypeId: dishTypeId,
                        dishTypeName: dishTypeName,
                        productId: ingredient.productId,
                        productName: product.name,
                        unitId: ingredient.unitId,
                        unitName: unit.name,
                        totalQuantity: totalQuantityForThisRecord
                    });
                }
            }
        }

        // Converter map para array e agrupar por dishTypeId
        const ingredientsArray = Array.from(ingredientsMap.values());

        // Agrupar por dishTypeId
        const byDishType = new Map<number, {
            dishTypeId: number;
            dishTypeName: string;
            totalDishes: number;
            ingredients: typeof ingredientsArray;
        }>();

        // Primeiro, calcular total de pratos por tipo
        const dishesByType = new Map<number, number>();
        for (const record of records) {
            const dish = record.dish;
            if (!dish) continue;
            if (filters?.dishTypeId && dish.dishTypeId !== filters.dishTypeId) continue;
            
            const currentTotal = dishesByType.get(dish.dishTypeId) || 0;
            dishesByType.set(dish.dishTypeId, currentTotal + record.quantity);
        }

        // Agrupar ingredientes por tipo de prato
        for (const ingredient of ingredientsArray) {
            if (!byDishType.has(ingredient.dishTypeId)) {
                const foundRecord = records.find(r => {
                    const dish = r.dish;
                    return dish && dish.dishTypeId === ingredient.dishTypeId;
                });
                const dishType = foundRecord?.dish?.dishType;

                byDishType.set(ingredient.dishTypeId, {
                    dishTypeId: ingredient.dishTypeId,
                    dishTypeName: ingredient.dishTypeName,
                    totalDishes: dishesByType.get(ingredient.dishTypeId) || 0,
                    ingredients: []
                });
            }

            byDishType.get(ingredient.dishTypeId)!.ingredients.push(ingredient);
        }

        return {
            byDishType: Array.from(byDishType.values()),
            totalIngredients: ingredientsArray,
            summary: {
                totalDishTypes: byDishType.size,
                totalProducts: new Set(ingredientsArray.map(i => i.productId)).size,
                totalQuantity: ingredientsArray.reduce((sum, ing) => sum + ing.totalQuantity, 0)
            }
        };
    }
}

import { Reservation } from "../Model/Reservation";
import { Meal } from "../Model/Meal";
import { User } from "../Model/User";
import { Dish } from "../Model/Dish";
import { Refeitorio } from "../Model/Refeitorio";
import { Canteen } from "../Model/Canteen";
import { ReservationQuantitiesCanteen } from "../Model/ReservationQuantitiesCanteen";

export class ReservationService {
    // Função helper para atualizar a tabela reservation_quantities_canteen
    private async updateReservationQuantitiesCanteen(
        mealId: number,
        refeitorioId: number,
        quantityChange: number,
        operation: "add" | "subtract"
    ) {
        try {
            const meal = await Meal.findByPk(mealId);
            if (!meal) return; // Se meal não existir, não fazer nada

            // Normalizar a data para o início do dia (remover horas)
            const mealDate = new Date(meal.date);
            mealDate.setHours(0, 0, 0, 0);

            // Procurar ou criar registo na tabela usando o refeitorioId da reserva (não da meal)
            // Isso permite que a mesma meal seja contabilizada separadamente por refeitório
            const [record, created] = await ReservationQuantitiesCanteen.findOrCreate({
                where: {
                    canteenId: meal.canteenId,
                    dishId: meal.dishId,
                    date: mealDate,
                    refeitorioId: refeitorioId, // Usar o refeitorioId da reserva, não da meal
                },
                defaults: {
                    canteenId: meal.canteenId,
                    dishId: meal.dishId,
                    date: mealDate,
                    refeitorioId: refeitorioId, // Usar o refeitorioId da reserva
                    quantity: 0,
                },
            });

            // Atualizar a quantity
            if (operation === "add") {
                record.quantity += quantityChange;
            } else if (operation === "subtract") {
                record.quantity = Math.max(0, record.quantity - quantityChange); // Não permitir valores negativos
            }

            await record.save();
        } catch (error) {
            console.error("Erro ao atualizar reservation_quantities_canteen:", error);
            // Não lançar erro para não quebrar o fluxo principal
        }
    }

    async createReservation(data: {
        status: "active" | "consumed" | "not consumed" | "pendent" | "canceled";
        reservationDate: Date;
        quantity: number;
        mealId: number;
        userId: number;
        refeitorioId: number;
    }) {
        const meal = await Meal.findByPk(data.mealId);
        if (!meal) throw new Error("MEAL_NOT_FOUND");

        const user = await User.findByPk(data.userId);
        if (!user) throw new Error("USER_NOT_FOUND");

        const refeitorio = await Refeitorio.findByPk(data.refeitorioId);
        if (!refeitorio) throw new Error("REFEITORIO_NOT_FOUND");

        const reservation = await Reservation.create(data);

        // Atualizar a tabela reservation_quantities_canteen apenas se a reserva não for cancelada
        // Usar o refeitorioId da reserva para segregar corretamente
        if (data.status !== "canceled") {
            await this.updateReservationQuantitiesCanteen(data.mealId, data.refeitorioId, data.quantity, "add");
        }

        return reservation;
    }

    async listReservations(filter?: { userId?: number; status?: string; refeitorioId?: number }) {
        const { Op } = require("sequelize");
        const where: any = {};
        if (filter?.userId) where.userId = filter.userId;
        if (filter?.refeitorioId) where.refeitorioId = filter.refeitorioId;
        // Excluir reservas canceladas sempre
        if (filter?.status && filter.status !== "all") {
            where.status = filter.status;
        } else {
            where.status = { [Op.ne]: "canceled" };
        }
        return await Reservation.findAll({ 
            where,
            include: [
                { model: User, as: "user", attributes: ["id", "name", "email"] },
                { model: Refeitorio, as: "refeitorio", attributes: ["id", "name"] },
                { 
                    model: Meal, 
                    as: "meal", 
                    attributes: ["id", "name", "date", "mealTypeId", "canteenId"],
                    include: [
                        { model: Dish, as: "dish", attributes: ["id", "name"] },
                        { model: Canteen, as: "canteen", attributes: ["id", "name"] }
                    ]
                }
            ]
        });
    }

    async updateStatus(id: number, status: "canceled" | "active" | "consumed" | "not consumed" | "pendent") {
        const reservation = await Reservation.findByPk(id);
        if (!reservation) throw new Error("RESERVATION_NOT_FOUND");
        
        const oldStatus = reservation.status;
        reservation.status = status;
        await reservation.save();

        // Atualizar a tabela reservation_quantities_canteen quando o status muda
        // Usar o refeitorioId da reserva para segregar corretamente
        // Se mudou de não-cancelado para cancelado, subtrair
        if (oldStatus !== "canceled" && status === "canceled") {
            await this.updateReservationQuantitiesCanteen(reservation.mealId, reservation.refeitorioId, reservation.quantity, "subtract");
        }
        // Se mudou de cancelado para não-cancelado, adicionar
        else if (oldStatus === "canceled" && status !== "canceled") {
            await this.updateReservationQuantitiesCanteen(reservation.mealId, reservation.refeitorioId, reservation.quantity, "add");
        }

        return reservation;
    }

    async liftTickets(id: number, quantityToLift: number) {
        const reservation = await Reservation.findByPk(id);
        if (!reservation) throw new Error("RESERVATION_NOT_FOUND");
        
        if (reservation.status !== "active") {
            throw new Error("RESERVATION_NOT_ACTIVE");
        }
        
        if (quantityToLift < 1 || quantityToLift > reservation.quantity) {
            throw new Error("INVALID_QUANTITY");
        }

        // Atualizar a reserva original
        const remainingQuantity = reservation.quantity - quantityToLift;
        
        if (remainingQuantity === 0) {
            // Se levantou todas, apenas marcar como consumed (não criar nova reserva)
            reservation.status = "consumed";
            await reservation.save();
            // Não precisa atualizar a tabela porque a quantity total permanece a mesma (só mudou o status)
        } else {
            // Se levantou parcial, criar nova reserva consumed e reduzir a quantidade da original
            await Reservation.create({
                status: "consumed",
                reservationDate: reservation.reservationDate,
                quantity: quantityToLift,
                mealId: reservation.mealId,
                userId: reservation.userId,
                refeitorioId: reservation.refeitorioId,
            });
            
            // Reduzir a quantidade da reserva original e manter active
            reservation.quantity = remainingQuantity;
            await reservation.save();
            // Não precisa atualizar a tabela porque a quantity total permanece a mesma (só mudou a distribuição)
        }
        
        return reservation;
    }

    async markUnconsumedReservations(targetDate?: Date) {
        const { Op } = require("sequelize");
        
        // Se não for fornecida uma data, usa a data atual
        const dateToCheck = targetDate || new Date();
        const checkDate = new Date(dateToCheck.getFullYear(), dateToCheck.getMonth(), dateToCheck.getDate());
        
        console.log(`🔍 [DEBUG] Data a verificar: ${checkDate.toISOString()}`);
        console.log(`🔍 [DEBUG] Data formatada: ${checkDate.toLocaleDateString("pt-PT")}`);

        // Buscar reservas ativas cuja data da refeição corresponde à data especificada
        const allActiveReservations = await Reservation.findAll({
            where: {
                status: "active",
            },
            include: [
                {
                    model: Meal,
                    as: "meal",
                    attributes: ["id", "name", "date"],
                },
            ],
        });

        console.log(`🔍 [DEBUG] Total de reservas ativas encontradas: ${allActiveReservations.length}`);

        // Filtrar apenas as que têm data da refeição na data especificada
        const targetReservations = allActiveReservations.filter((reservation: any) => {
            if (!reservation.meal || !reservation.meal.date) {
                console.log(`🔍 [DEBUG] Reserva ${reservation.id} sem meal ou meal.date`);
                return false;
            }
            const mealDate = new Date(reservation.meal.date);
            const mealDateOnly = new Date(mealDate.getFullYear(), mealDate.getMonth(), mealDate.getDate());
            const matches = mealDateOnly.getTime() === checkDate.getTime();
            
            if (matches) {
                console.log(`🔍 [DEBUG] Reserva com o ID ${reservation.id} MATCH! Meal date: ${mealDateOnly.toLocaleDateString("pt-PT")}, Check date: ${checkDate.toLocaleDateString("pt-PT")}`);
            } else {
                console.log(`🔍 [DEBUG] Reserva com o ID${reservation.id} não match. Meal date: ${mealDateOnly.toLocaleDateString("pt-PT")}, Check date: ${checkDate.toLocaleDateString("pt-PT")}`);
            }
            
            return matches;
        });

        console.log(`🔍 [DEBUG] Reservas que correspondem à data: ${targetReservations.length}`);

        let updatedCount = 0;
        for (const reservation of targetReservations) {
            console.log(`🔄 [DEBUG] Marcando reserva ${reservation.id} como "not consumed"`);
            reservation.status = "not consumed";
            await reservation.save();
            updatedCount++;
        }

        const dateStr = checkDate.toLocaleDateString("pt-PT");
        return {
            updated: updatedCount,
            message: `${updatedCount} ids encontrados de refeições marcadas, foram atualizadas como não consumidas na data de ${dateStr}`,
        };
    }
}

import { RecipeService } from "./RecipeService";
import { IngredientService } from "./IngredientService";
import { BatchService } from "./BatchService";
import { convertQuantity } from "../utils/unitConversion";
import { UnitService } from "./UnitService";
import { UnitEnum } from "../Model/Unit";

const recipeService = new RecipeService();
const ingredientService = new IngredientService();
const batchService = new BatchService();
const unitService = new UnitService();

export class StatisticsService {

    async getBioProductsPercentageForRecipe() {
        const result: { recipe: any; percentage: number }[] = [];

        const recipes = await recipeService.listRecipes();
        if (!recipes?.length) throw new Error("NO_RECIPES_FOUND");

        const batches = await batchService.listBatches();
        if (!batches?.length) throw new Error("NO_BATCHES_FOUND");

        for (const recipe of recipes) {
            let totalQuantity = 0;
            let totalBioQuantity = 0;

            let baseUnit: UnitEnum | null = null;

            for (const ingredientId of recipe.ingredients) {
                const ingredient = await ingredientService.getIngredientById(ingredientId);
                if (!ingredient) throw new Error("INGREDIENT_NOT_FOUND");

                const unit = await unitService.getUnitById(ingredient.unitId);
                if (!unit) throw new Error("UNIT_NOT_FOUND");

                // Definir unidade base
                if (!baseUnit) {
                    if (
                        unit.name === UnitEnum.Kilogram ||
                        unit.name === UnitEnum.Gram
                    ) {
                        baseUnit = UnitEnum.Gram;
                    } else if (
                        unit.name === UnitEnum.Liter ||
                        unit.name === UnitEnum.Milliliter
                    ) {
                        baseUnit = UnitEnum.Milliliter;
                    } else {
                        baseUnit = unit.name;
                    }
                }

                // Bloquear conversões inválidas
                const incompatible =
                    (baseUnit === UnitEnum.Gram &&
                        ![UnitEnum.Gram, UnitEnum.Kilogram].includes(unit.name)) ||
                    (baseUnit === UnitEnum.Milliliter &&
                        ![UnitEnum.Liter, UnitEnum.Milliliter].includes(unit.name));

                if (incompatible) {
                    continue;
                }

                const quantityInBaseUnit =
                    unit.name === baseUnit
                        ? ingredient.quantity
                        : convertQuantity(
                            ingredient.quantity,
                            unit.name,
                            baseUnit
                        );

                totalQuantity += quantityInBaseUnit;

                const isBio = batches.some(
                    batch => batch.productId === ingredient.productId && batch.bio
                );

                if (isBio) {
                    totalBioQuantity += quantityInBaseUnit;
                }
            }
            
            result.push({
                recipe,
                percentage:
                    totalQuantity === 0
                        ? 0
                        : Number(((totalBioQuantity / totalQuantity) * 100).toFixed(2)),
            });
        }

        return result;
    }
}

import {Batch} from "../Model/Batch";
import {Product} from "../Model/Product";
import {Unit} from "../Model/Unit";
import {Stock} from "../Model/Stock";
import {BatchService} from "../Service/BatchService";

const batchService = new BatchService();

export class StockService {
    async createStock(data: {
        updatedDate: Date;
        minimumCapacity: number;
        maximumCapacity: number;
        currentQuantity: number;
        batches: number[];
    }) {
        // validar se a capacidade máxima é maior que a capacidade mínima
        if (data.maximumCapacity <= data.minimumCapacity) throw new Error("MAXIMUM_CAPACITY_MUST_BE_GREATER_THAN_MINIMUM_CAPACITY");

        // validar se a quantidade atual está entre a capacidade mínima e máxima
        if (data.currentQuantity < data.minimumCapacity || data.currentQuantity > data.maximumCapacity) {
            throw new Error("CURRENT_QUANTITY_MUST_BE_BETWEEN_MINIMUM_AND_MAXIMUM_CAPACITY");
        }

        // validar existência de Id's e a quantity dos produtos
        for (const batches of data.batches) {
            const batch = await Batch.findByPk(batches);
            if (!batch) throw new Error("BATCH_NOT_FOUND");
        }

        return await Stock.create(data);
    }

    async listStocks() {
        return await Stock.findAll();
    }

    async getStockById(id: number) {
        const stock = await Stock.findByPk(id);
        if (!stock) throw new Error("STOCK_NOT_FOUND");
        return stock;
    }

    async getStockProducts(stock: Stock) {
        const fullStock = await this.getStockById(stock.id);
        if (!fullStock) throw new Error("STOCK_NOT_FOUND");

        const productMap = new Map<number, { quantity: number; unitId: number }>();

        for (const batchId of fullStock.batches) {
            const batch = await batchService.getBatchById(batchId);
            if (!batch) continue;

            if (productMap.has(batch.productId)) {
                const entry = productMap.get(batch.productId)!;
                entry.quantity += batch.quantity;
            } else {
                productMap.set(batch.productId, {
                    quantity: batch.quantity,
                    unitId: batch.unitId
                });
            }
        }

        return Array.from(productMap.entries()).map(([productId, data]) => ({
            productId,
            quantity: data.quantity,
            unitId: data.unitId,
        }));
    }

}

import { User } from "../Model/User";
import { Canteen } from "../Model/Canteen";
import { Refeitorio } from "../Model/Refeitorio";
import bcrypt from "bcrypt";
import { OrderService } from "./OrderService";
import { NeededProduct } from "../Model/NeededProduct";
import { generateOrdersFromNeededProducts } from "../utils/generateOrdersFromNeededProducts";

const SECRET_KEY = process.env.SECRET_KEY || "minha_chave_secreta";

export class UserService {
  // Criar novo utilizador
  static async createUser(name: string, email: string, password: string, role: "Supplier" | "NetworkManager" | "Nutritionist" | "Student" | "Visitor" | "NursingHome" | "RefectoryStaff"| "StockManager"| "CanteenManager" | "RefectoryManager", refeitorioId?: number, canteenId?: number) {
    const hashedPassword = await bcrypt.hash(password, 10);
    const user = await User.create({ name, email, password: hashedPassword, role, status: "enabled", refeitorioId, canteenId });
    return user;
  }

  // Verificar se email existe
  static async findByEmail(email: string) {
    return await User.findOne({ where: { email } });
  }

  // Login
  static async login(email: string, password: string) {
    const user = await User.findOne({ 
      where: { email },
      include: [
        {
          model: Canteen,
          as: "canteen",
          attributes: ["id", "name"],
          required: false,
        },
        {
          model: Refeitorio,
          as: "refeitorio",
          attributes: ["id", "name"],
          required: false,
        },
      ],
    });

    if (!user) throw new Error("Email inválido.");
    if ((user as any).status === "disabled") throw new Error("Conta desativada.");

    const validPassword = await bcrypt.compare(password, user.password as string);
    if (!validPassword) throw new Error("Senha incorreta.");

    // Retorna dados do user sem password, incluindo informações da cantina/refeitório
    return {
      id: user.id,
      name: user.name,
      email: user.email,
      role: (user as any).role || "user",
      status: (user as any).status || "enabled",
      canteenId: (user as any).canteenId || null,
      refeitorioId: (user as any).refeitorioId || null,
      canteen: (user as any).canteen ? { id: (user as any).canteen.id, name: (user as any).canteen.name } : null,
      refeitorio: (user as any).refeitorio ? { id: (user as any).refeitorio.id, name: (user as any).refeitorio.name } : null,
    };
  }

  // Encontrar utilizador por ID
  static async findById(id: number) {
    return await User.findByPk(id, {
      attributes: { exclude: ['password'] } // Excluir password dos resultados
    });
  }

  static async startQuarantine(id: number) {
    const user = await User.findByPk(id); 
    if (!user) {
      throw new Error("Utilizador não encontrado.");
    }
    user.status = "quarantine";
    await user.save();

    if(user.role === "Supplier") {
    // se o supplier tiver orders, cancelear e meter neededProducts como needed outra vez
    const orders = await OrderService.getByUserId(id);
    let needProductsIds = [];
    for(const order of orders) {
        await OrderService.updateStatus(order.id, "cancelled");
        needProductsIds.push(order.neededProductId);
    }

    for(const npId of needProductsIds) {
        const neededProduct = await NeededProduct.findByPk(npId);
        if(neededProduct) {
            neededProduct.status = "needed";
            await neededProduct.save();
        }
    }

    // gerar novas encomendas dos neededProducts atualizados para outros suppliers
    await generateOrdersFromNeededProducts();
    }

    return user;
  }

  static async endQuarantine(id: number) {
    const user = await User.findByPk(id); 
    if (!user) {
      throw new Error("Utilizador não encontrado.");
    }
    user.status = "enabled";
    await user.save();
    return user;
  }
}

import { WasteReport } from "../Model/WasteReport";
import { Meal } from "../Model/Meal";
import { User } from "../Model/User";
import { Reservation } from "../Model/Reservation";
import { Dish } from "../Model/Dish";
import { DishType } from "../Model/DishType";
import { Refeitorio } from "../Model/Refeitorio";

export class WasteReportService {
    async createWasteReport(data: {
        wastePercentage: number;
        mealId: number;
        reservationId?: number;
        reportedBy: number;
        refeitorioId: number;
    }) {
        // Validar mealId
        const meal = await Meal.findByPk(data.mealId);
        if (!meal) throw new Error("MEAL_NOT_FOUND");

        // Validar reportedBy (deve ser canteen staff)
        const user = await User.findByPk(data.reportedBy);
        if (!user) throw new Error("USER_NOT_FOUND");
        if (user.role !== "RefectoryStaff") {
            throw new Error("ONLY_CANTEEN_STAFF_CAN_REPORT");
        }

        // Validar refeitorioId
        const refeitorio = await Refeitorio.findByPk(data.refeitorioId);
        if (!refeitorio) throw new Error("REFEITORIO_NOT_FOUND");
        
        // Validar que o refeitorioId corresponde ao refeitório do utilizador
        if (user.refeitorioId !== data.refeitorioId) {
            throw new Error("USER_CAN_ONLY_REPORT_FOR_OWN_REFEITORIO");
        }

        // Validar reservationId se fornecido
        if (data.reservationId) {
            const reservation = await Reservation.findByPk(data.reservationId);
            if (!reservation) throw new Error("RESERVATION_NOT_FOUND");
        }

        // Validar wastePercentage (0-100)
        if (data.wastePercentage < 0 || data.wastePercentage > 100) {
            throw new Error("INVALID_WASTE_PERCENTAGE");
        }

        return await WasteReport.create({
            wastePercentage: data.wastePercentage,
            mealId: data.mealId,
            reservationId: data.reservationId,
            reportedBy: data.reportedBy,
            refeitorioId: data.refeitorioId,
            reportedAt: new Date(),
        });
    }

    async getWasteReportsByMeal(mealId: number) {
        const meal = await Meal.findByPk(mealId);
        if (!meal) throw new Error("MEAL_NOT_FOUND");

        return await WasteReport.findAll({
            where: { mealId },
            include: [
                { model: User, as: "reporter", attributes: ["id", "name", "email"] },
            ],
            order: [["reportedAt", "DESC"]],
        });
    }

    async getWasteReportsByDate(date: Date) {
        const { Op } = require("sequelize");
        const startOfDay = new Date(date);
        startOfDay.setHours(0, 0, 0, 0);
        const endOfDay = new Date(date);
        endOfDay.setHours(23, 59, 59, 999);

        return await WasteReport.findAll({
            where: {
                reportedAt: {
                    [Op.between]: [startOfDay, endOfDay],
                },
            },
            include: [
                { model: Meal, as: "meal", attributes: ["id", "name", "date"] },
                { model: User, as: "reporter", attributes: ["id", "name", "email"] },
            ],
            order: [["reportedAt", "DESC"]],
        });
    }

    async getWasteReportsForConsumedMeals(date: Date) {
        const { Op } = require("sequelize");
        
        // Buscar todas as meals consumidas na data especificada
        const startOfDay = new Date(date);
        startOfDay.setHours(0, 0, 0, 0);
        const endOfDay = new Date(date);
        endOfDay.setHours(23, 59, 59, 999);

        // Buscar reservas consumidas com meals na data especificada
        const consumedReservations = await Reservation.findAll({
            where: {
                status: "consumed",
            },
            include: [
                {
                    model: Meal,
                    as: "meal",
                    where: {
                        date: {
                            [Op.between]: [startOfDay, endOfDay],
                        },
                    },
                    attributes: ["id", "name", "date"],
                },
            ],
        });

        // Agrupar por mealId para obter meals únicas
        const mealIds = new Set<number>();
        consumedReservations.forEach((reservation: any) => {
            if (reservation.meal) {
                mealIds.add(reservation.meal.id);
            }
        });

        // Verificar quais meals já têm report
        const existingReports = await WasteReport.findAll({
            where: {
                mealId: {
                    [Op.in]: Array.from(mealIds),
                },
            },
            attributes: ["mealId"],
        });

        const reportedMealIds = new Set(existingReports.map((r) => r.mealId));

        // Retornar meals que precisam de report
        const mealsNeedingReport: number[] = [];
        mealIds.forEach((mealId) => {
            if (!reportedMealIds.has(mealId)) {
                mealsNeedingReport.push(mealId);
            }
        });

        return {
            mealsNeedingReport,
            totalConsumedMeals: mealIds.size,
            reportedMeals: reportedMealIds.size,
        };
    }

    async getWasteReportStatistics(filter?: {
        mealId?: number;
        dateRangeStart?: Date;
        dateRangeEnd?: Date;
        date?: Date;
        period?: "day" | "week" | "month" | "year";
        dishTypeId?: number;
        mealTypeId?: number; // ID do tipo de refeição (1=Almoço, 2=Jantar)
        dayOfWeek?: number;
        refeitorioId?: number; // ID do refeitório (para filtrar por refeitório)
    }) {
        const { Op } = require("sequelize");
        
        const whereClause: any = {};
        
        // Filtro por mealId
        if (filter?.mealId) {
            whereClause.mealId = filter.mealId;
        }
        
        // Filtro por refeitorioId (obrigatório para segregar reports por refeitório)
        if (filter?.refeitorioId) {
            whereClause.refeitorioId = filter.refeitorioId;
        }
        
        // Construir filtro de data baseado nos parâmetros
        let dateFilter: any = {};
        let hasPeriodFilter = false;
        
        // Se houver filtro de período (date + period), filtrar pela data da refeição
        if (filter?.date && filter?.period) {
            hasPeriodFilter = true;
            const targetDate = new Date(filter.date);
            let startDate: Date;
            let endDate: Date;

            if (filter.period === "day") {
                startDate = new Date(targetDate.getFullYear(), targetDate.getMonth(), targetDate.getDate());
                endDate = new Date(targetDate.getFullYear(), targetDate.getMonth(), targetDate.getDate(), 23, 59, 59, 999);
            } else if (filter.period === "week") {
                const dayOfWeek = targetDate.getDay();
                const diff = dayOfWeek === 0 ? -6 : 1 - dayOfWeek;
                startDate = new Date(targetDate);
                startDate.setDate(targetDate.getDate() + diff);
                startDate.setHours(0, 0, 0, 0);
                endDate = new Date(startDate);
                endDate.setDate(startDate.getDate() + 6);
                endDate.setHours(23, 59, 59, 999);
            } else if (filter.period === "month") {
                startDate = new Date(targetDate.getFullYear(), targetDate.getMonth(), 1);
                endDate = new Date(targetDate.getFullYear(), targetDate.getMonth() + 1, 0, 23, 59, 59, 999);
            } else if (filter.period === "year") {
                startDate = new Date(targetDate.getFullYear(), 0, 1);
                startDate.setHours(0, 0, 0, 0);
                endDate = new Date(targetDate.getFullYear() + 1, 0, 0, 23, 59, 59, 999);
            } else {
                startDate = new Date(targetDate.getFullYear(), targetDate.getMonth(), targetDate.getDate());
                endDate = new Date(targetDate.getFullYear(), targetDate.getMonth(), targetDate.getDate(), 23, 59, 59, 999);
            }
            
            dateFilter = {
                [Op.gte]: startDate,
                [Op.lte]: endDate,
            };
        } else if (filter?.dateRangeStart && filter?.dateRangeEnd && !filter?.dayOfWeek) {
            // Se houver dateRangeStart e dateRangeEnd sem dayOfWeek, pode ser filtro de período ou de report
            // Se não houver period, assumir que é filtro de período (data da refeição)
            hasPeriodFilter = true;
            const startDate = new Date(filter.dateRangeStart);
            startDate.setHours(0, 0, 0, 0);
            const endDate = new Date(filter.dateRangeEnd);
            endDate.setHours(23, 59, 59, 999);
            
            dateFilter = {
                [Op.gte]: startDate,
                [Op.lte]: endDate,
            };
        } else if ((filter?.dateRangeStart || filter?.dateRangeEnd) && !hasPeriodFilter) {
            // Filtro por data (quando foi reportado) - usar reportedAt apenas se não houver filtro de período
            whereClause.reportedAt = {};
            if (filter.dateRangeStart) {
                const start = new Date(filter.dateRangeStart);
                start.setHours(0, 0, 0, 0);
                whereClause.reportedAt[Op.gte] = start;
            }
            if (filter.dateRangeEnd) {
                const end = new Date(filter.dateRangeEnd);
                end.setHours(23, 59, 59, 999);
                whereClause.reportedAt[Op.lte] = end;
            }
        }

        // Configurar include do Meal com filtros
        const mealIncludeOptions: any = {
            model: Meal,
            as: "meal",
            attributes: ["id", "name", "date", "mealTypeId"],
            required: true,
            include: [
                {
                    model: Dish,
                    as: "dish",
                    attributes: ["id", "name", "dishTypeId"],
                    required: true,
                    include: [
                        {
                            model: DishType,
                            as: "dishType",
                            attributes: ["id", "name"],
                            required: true,
                        },
                    ],
                },
            ],
        };

        // Adicionar filtro de data e mealTypeId na meal se especificado
        const mealWhere: any = {};
        if (dateFilter && Object.keys(dateFilter).length > 0) {
            mealWhere.date = dateFilter;
        }
        if (filter?.mealTypeId) {
            mealWhere.mealTypeId = filter.mealTypeId;
        }
        if (Object.keys(mealWhere).length > 0) {
            mealIncludeOptions.where = mealWhere;
        }

        // Adicionar filtro de tipo de prato
        if (filter?.dishTypeId) {
            const dishInclude = mealIncludeOptions.include[0];
            if (dishInclude && dishInclude.model === Dish) {
                if (!dishInclude.where) {
                    dishInclude.where = {};
                }
                dishInclude.where.dishTypeId = filter.dishTypeId;
            }
        }

        const whereOptions = Object.keys(whereClause).length > 0 ? { where: whereClause } : {};
        
        const reports = await WasteReport.findAll({
            ...whereOptions,
            include: [
                mealIncludeOptions,
                {
                    model: User,
                    as: "reporter",
                    attributes: ["id", "name", "email"],
                    required: false,
                },
            ],
            order: [["reportedAt", "DESC"]],
        });

        // Filtrar por dia da semana se especificado
        let filteredReports = reports;
        if (filter?.dayOfWeek !== undefined) {
            const targetDayOfWeek = filter.dayOfWeek;
            const rangeStart = filter.dateRangeStart ? new Date(filter.dateRangeStart) : null;
            const rangeEnd = filter.dateRangeEnd ? new Date(filter.dateRangeEnd) : null;
            
            filteredReports = reports.filter((report: any) => {
                if (!report.meal || !report.meal.date) return false;
                const mealDate = new Date(report.meal.date);
                const dayOfWeek = mealDate.getDay();
                
                if (dayOfWeek !== targetDayOfWeek) return false;
                
                if (rangeStart || rangeEnd) {
                    mealDate.setHours(0, 0, 0, 0);
                    if (rangeStart) {
                        rangeStart.setHours(0, 0, 0, 0);
                        if (mealDate < rangeStart) return false;
                    }
                    if (rangeEnd) {
                        rangeEnd.setHours(23, 59, 59, 999);
                        if (mealDate > rangeEnd) return false;
                    }
                }
                
                return true;
            });
        } else if (filter?.period === "day" && filter?.date) {
            // Filtrar por dia específico - garantir que apenas reports do dia filtrado sejam incluídos
            const targetDate = new Date(filter.date);
            const targetDateStr = targetDate.toISOString().split('T')[0];
            
            filteredReports = reports.filter((report: any) => {
                if (!report.meal || !report.meal.date) return false;
                const mealDate = new Date(report.meal.date);
                const mealDateStr = mealDate.toISOString().split('T')[0];
                return mealDateStr === targetDateStr;
            });
        }

        // Agrupar por meal
        const byMeal: Record<number, {
            mealId: number;
            mealName: string;
            mealDate: string;
            mealTypeId?: number;
            dishTypeId?: number;
            dishName?: string;
            reports: any[];
            averageWaste: number;
            totalReports: number;
        }> = {};

        filteredReports.forEach((report: any) => {
            const mealId = report.mealId;
            if (!byMeal[mealId]) {
                const mealDate = report.meal?.date ? new Date(report.meal.date).toISOString() : new Date().toISOString();
                byMeal[mealId] = {
                    mealId,
                    mealName: report.meal?.name || `Meal ID: ${mealId}`,
                    mealDate: mealDate,
                    mealTypeId: report.meal?.mealTypeId,
                    dishTypeId: report.meal?.dish?.dishTypeId,
                    dishName: report.meal?.dish?.name,
                    reports: [],
                    averageWaste: 0,
                    totalReports: 0,
                };
            }
            byMeal[mealId].reports.push(report);
        });

        // Calcular média por meal
        Object.values(byMeal).forEach((mealData) => {
            const totalWaste = mealData.reports.reduce((sum, r) => sum + r.wastePercentage, 0);
            mealData.averageWaste = mealData.reports.length > 0 ? totalWaste / mealData.reports.length : 0;
            mealData.totalReports = mealData.reports.length;
        });

        // Filtrar byMeal baseado no filtro de período (se necessário)
        let filteredByMeal = Object.values(byMeal);
        
        if (filter?.period === "day" && filter?.date) {
            // Se for filtro por dia, mostrar apenas meals desse dia
            const targetDate = new Date(filter.date);
            const targetDateStr = targetDate.toISOString().split('T')[0];
            filteredByMeal = filteredByMeal.filter((mealData) => {
                const mealDate = new Date(mealData.mealDate);
                const mealDateStr = mealDate.toISOString().split('T')[0];
                return mealDateStr === targetDateStr;
            });
        } else if (filter?.dateRangeStart && filter?.dateRangeEnd && !filter?.dayOfWeek) {
            // Se for filtro por intervalo, mostrar apenas meals no intervalo
            const rangeStart = new Date(filter.dateRangeStart);
            rangeStart.setHours(0, 0, 0, 0);
            const rangeEnd = new Date(filter.dateRangeEnd);
            rangeEnd.setHours(23, 59, 59, 999);
            
            filteredByMeal = filteredByMeal.filter((mealData) => {
                const mealDate = new Date(mealData.mealDate);
                return mealDate >= rangeStart && mealDate <= rangeEnd;
            });
        } else if (filter?.period === "week" && filter?.date) {
            // Se for filtro por semana, mostrar apenas meals da semana
            const targetDate = new Date(filter.date);
            const dayOfWeek = targetDate.getDay();
            const diff = dayOfWeek === 0 ? -6 : 1 - dayOfWeek;
            const weekStart = new Date(targetDate);
            weekStart.setDate(targetDate.getDate() + diff);
            weekStart.setHours(0, 0, 0, 0);
            
            const weekEnd = new Date(weekStart);
            weekEnd.setDate(weekStart.getDate() + 6);
            weekEnd.setHours(23, 59, 59, 999);
            
            filteredByMeal = filteredByMeal.filter((mealData) => {
                const mealDate = new Date(mealData.mealDate);
                return mealDate >= weekStart && mealDate <= weekEnd;
            });
        } else if (filter?.period === "month" && filter?.date) {
            // Se for filtro por mês, mostrar apenas meals do mês
            const targetDate = new Date(filter.date);
            const monthStart = new Date(targetDate.getFullYear(), targetDate.getMonth(), 1);
            const monthEnd = new Date(targetDate.getFullYear(), targetDate.getMonth() + 1, 0, 23, 59, 59, 999);
            
            filteredByMeal = filteredByMeal.filter((mealData) => {
                const mealDate = new Date(mealData.mealDate);
                return mealDate >= monthStart && mealDate <= monthEnd;
            });
        } else if (filter?.period === "year" && filter?.date) {
            // Se for filtro por ano, mostrar apenas meals do ano
            const targetDate = new Date(filter.date);
            const yearStart = new Date(targetDate.getFullYear(), 0, 1);
            yearStart.setHours(0, 0, 0, 0);
            const yearEnd = new Date(targetDate.getFullYear() + 1, 0, 0, 23, 59, 59, 999);
            
            filteredByMeal = filteredByMeal.filter((mealData) => {
                const mealDate = new Date(mealData.mealDate);
                mealDate.setHours(0, 0, 0, 0);
                return mealDate >= yearStart && mealDate <= yearEnd;
            });
        }

        // Recalcular totais com base nos dados filtrados
        // Isso garante que os totais reflitam apenas o período filtrado
        const allReports = filteredByMeal.flatMap(m => m.reports);
        const totalReports = allReports.length;
        const averageWaste = totalReports > 0
            ? allReports.reduce((sum, r) => sum + r.wastePercentage, 0) / totalReports
            : 0;

        return {
            totalReports,
            averageWaste,
            byMeal: filteredByMeal,
        };
    }
}

import { Request, Response, NextFunction } from "express";
import jwt, { JwtPayload } from "jsonwebtoken";

const SECRET_KEY = process.env.JWT_SECRET;

if (!SECRET_KEY) {
  throw new Error("JWT_SECRET não definido no .env");
}

export const authMiddleware = (
  req: Request,
  res: Response,
  next: NextFunction,
) => {
  const authHeader = req.headers["authorization"];
  const token = authHeader?.split(" ")[1]; // "Bearer <token>"

  if (!token) {
    return res.status(401).json({ message: "Token não fornecido" });
  }

  try {
    const decoded = jwt.verify(token, SECRET_KEY) as JwtPayload;

    // Garantir que id e role existem
    if (!decoded.id || !decoded.role) {
      return res.status(403).json({ message: "Token inválido" });
    }

    // anexamos o user ao request
    (req as any).user = { id: decoded.id, role: decoded.role };

    next();
  } catch (err) {
    return res.status(403).json({ message: "Token inválido ou expirado" });
  }
};

import { Request, Response, NextFunction } from "express";

export const authorizeRoles = (...roles: string[]) => {
  return (req: Request, res: Response, next: NextFunction) => {
    const user = (req as any).user; // vem do authMiddleware

    if (!user) {
      return res.status(401).json({ message: "Não autenticado" });
    }

    if (!roles.includes(user.role)) {
      return res.status(403).json({ message: "Sem permissão para aceder" });
    }

    next();
  };
};

import { Op } from "sequelize";
import { Order } from "../Model/Order";
import { Meal } from "../Model/Meal";
import { AverageReservation } from "../Model/AverageReservation";
import { Reservation } from "../Model/Reservation";
import { User } from "../Model/User";
import { Notification } from "../Model/Notification";
import { NeededProduct } from "../Model/NeededProduct";
import { Product } from "../Model/Product";

const DAYS_BEFORE_CHECK = 4;
export async function adjustOrdersAfterReservations() {
  const pendingOrders = await Order.findAll({
    where: { status: "pending" }
  });

  if (!pendingOrders.length) return;

  const stockManagers = await User.findAll({
    where: { role: "StockManager" }
  });

   let anySuccess = false;

  for (const order of pendingOrders) {
    const neededProduct = await NeededProduct.findByPk(order.neededProductId)
    const meal = await Meal.findByPk(neededProduct?.mealId);
    const product = await Product.findByPk(order.productId);
    if (!meal) continue;

    // Verifica se a refeição está em 0–4 dias
    const today = new Date();
    const mealDate = new Date(meal.date);
    const diffDays = Math.ceil((mealDate.getTime() - today.getTime()) / (1000 * 60 * 60 * 24));
    if (diffDays < 0 || diffDays > DAYS_BEFORE_CHECK) continue;

    // Total de reservas reais para esta refeição
    const realReservations = await Reservation.sum("quantity", {
      where: {
        mealId: meal.id,
        status: "active" // ou "pendent", conforme lógica
      }
    });

    const avgReservation = await AverageReservation.findOne({
      where: {
        dishId: meal.dishId,
        typeOfMealId: meal.mealTypeId,
        canteenId: meal.canteenId
      }
    });

    if (!avgReservation) continue;

    // Desvio percentual
    const deviation =
      (realReservations - avgReservation.avgReservations) /
      avgReservation.avgReservations;

    // Atualiza quantity da order
    const adjustedQuantity =
      order.quantity * (realReservations / avgReservation.avgReservations);

    if (adjustedQuantity <= 0) {
      order.quantity = 0;
      order.status = "cancelled";
      await order.save();
      anySuccess = true;
      continue;
    }

    order.quantity = adjustedQuantity;
    order.status = "confirmed"; // passa a confirmed
    await order.save();
    anySuccess = true;

    // 🚨 Notificação se desvio > 10%
    if (Math.abs(deviation) > 0.1) {
      for (const sm of stockManagers) {
        await Notification.create({
          userId: sm.id,
          title: "Desvio significativo nas reservas",
          body: `As reservas reais diferem em ${(deviation * 100).toFixed(
            1
          )}% face ao planeado para o produto ${product?.name} na refeição de ${meal.date.toISOString().split("T")[0]}.`,
          status: "sent"
        });
      }
    }
  }
  if (anySuccess) {
    for (const sm of stockManagers) {
      await Notification.create({
        userId: sm.id,
        title: "Encomendas ajustadas após reservas",
        body: "As encomendas pendentes foram ajustadas com base nas reservas e confirmadas.",
        status: "sent"
      });
    }
  }
}
